INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('huydepzai121/skill/ffmpeg', 'community', 'huydepzai121', 'skill', 'huydepzai121/skill', 'ffmpeg', 0, 0, 75, '2026-02-18T01:08:43.404Z', '2026-02-18T03:11:52.688Z', NULL, '{"id":"huydepzai121/skill/ffmpeg","name":"ffmpeg","description":{"zh":"FFmpeg 是一个开源的多媒体框架，用于处理视频、音频和其他多媒体文件和流媒体。它提供了命令行工具和库用于记录、转换和流媒体音频和视频。","ja":"FFmpeg は、ビデオ、オーディオ、他のマルチメディアファイルとストリームを処理するオープンソースのマルチメディアフレームワークです。レコーディング、変換、ストリーミング用のコマンドラインツールとライブラリを提供します。","ko":"FFmpeg는 비디오, 오디오 및 기타 멀티미디어 파일과 스트림을 처리하는 오픈소스 멀티미디어 프레임워크입니다. 녹음, 변환 및 스트리밍을 위한 명령줄 도구와 라이브러리를 제공합니다.","es":"FFmpeg es un framework de multimedia de código abierto que maneja archivos y flujos de video, audio y otros medios","fr":"FFmpeg est un cadre multimédia open-source qui gère les fichiers et les flux de vidéo, d''audio et d''autres médias","de":"FFmpeg ist ein Open-Source-Multimedia-Framework, das Dateien und Streams von Video, Audio und anderen Medien verarbeitet","pt":"O FFmpeg é uma ferramenta de código aberto para processamento de áudio e vídeo, permitindo a conversão, codificação e transmissão de mídia","ru":"FFmpeg - это открытое мультимедийное платформа для обработки аудио и видео, позволяющая конвертировать, кодировать и транслировать мультимедиа","ar":"ffmpeg هو إطار مفتوح المصدر لمعالجة الصوت والفيديو، يسمح بتحويل وترميز ونقل وسائط متعددة","en":""},"seo":{"title":{"zh":"FFmpeg 技术：多媒体处理和转码","ja":"FFmpeg 技術：マルチメディア処理と変換","ko":"FFmpeg 기술: 멀티미디어 처리 및 변환","es":"FFmpeg: Framework de multimedia de código abierto","fr":"FFmpeg: Cadre multimédia open-source","de":"FFmpeg: Open-Source-Multimedia-Framework","pt":"FFmpeg: Ferramenta de Multimídia de Código Aberto","ru":"FFmpeg: Открытая Мультимедийная Платформа","ar":"ffmpeg: إطار مفتوح المصدر للمULTIMEDIA","en":"ffmpeg"},"description":{"zh":"FFmpeg 是一个开源的多媒体框架，用于处理视频、音频和其他多媒体文件和流媒体。它提供了命令行工具和库用于记录、转换和流媒体音频和视频。","ja":"FFmpeg は、ビデオ、オーディオ、他のマルチメディアファイルとストリームを処理するオープンソースのマルチメディアフレームワークです。レコーディング、変換、ストリーミング用のコマンドラインツールとライブラリを提供します。","ko":"FFmpeg는 비디오, 오디오 및 기타 멀티미디어 파일과 스트림을 처리하는 오픈소스 멀티미디어 프레임워크입니다. 녹음, 변환 및 스트리밍을 위한 명령줄 도구와 라이브러리를 제공합니다.","es":"FFmpeg es un framework de multimedia de código abierto que maneja archivos y flujos de video, audio y otros medios","fr":"FFmpeg est un cadre multimédia open-source qui gère les fichiers et les flux de vidéo, d''audio et d''autres médias","de":"FFmpeg ist ein Open-Source-Multimedia-Framework, das Dateien und Streams von Video, Audio und anderen Medien verarbeitet","pt":"O FFmpeg é uma ferramenta de código aberto para processamento de áudio e vídeo, permitindo a conversão, codificação e transmissão de mídia","ru":"FFmpeg - это открытое мультимедийное платформа для обработки аудио и видео, позволяющая конвертировать, кодировать и транслировать мультимедиа","ar":"ffmpeg هو إطار مفتوح المصدر لمعالجة الصوت والفيديو، يسمح بتحويل وترميز ونقل وسائط متعددة","en":""},"definition":{"en":""},"features":{"zh":["多媒体文件转码","视频编码和解码","音频文件处理","实时流媒体"],"ja":["マルチメディアファイルの変換","ビデオエンコードとデコード","オーディオファイルの処理","リアルタイムストリーミング"],"ko":["멀티미디어 파일 변환","비디오 인코딩 및 디코딩","오디오 파일 처리","실시간 스트리밍"],"es":["Conversión de archivos de medios entre formatos","Codificación y decodificación de video con diferentes codecs","Procesamiento de archivos de audio","Transmisión en vivo","Compatibilidad con múltiples formatos de archivo","Herramientas de línea de comandos personalizables"],"fr":["Conversion de fichiers médias entre formats","Encodage et décodage de la vidéo avec différents codecs","Traitement de fichiers audio","Diffusion en direct","Compatibilité avec de nombreux formats de fichiers","Outils en ligne de commande personnalisables"],"de":["Konvertierung von Mediadateien zwischen Formaten","Codierung und Decodierung von Video mit unterschiedlichen Codecs","Verarbeitung von Audiodateien","Live-Streaming","Kompatibilität mit zahlreichen Dateiformaten","Anpassbare Kommandozeilen-Tools"],"pt":["Conversão de arquivos de mídia entre formatos","Codificação e decodificação de vídeo com diferentes codecs","Processamento de arquivos de áudio","Transmissão ao vivo","Bibliotecas e ferramentas de linha de comando"],"ru":["Конвертация мультимедийных файлов между форматами","Кодирование и декодирование видео с разными кодеками","Обработка аудиофайлов","Прямая трансляция","Библиотеки и инструменты командной строки"],"ar":["تحويل ملفات الوسائط بين التنسيقات","ترميز وفك ترميز الفيديو باستخدام ترميزات مختلفة","معالجة ملفات الصوت","نقل مباشر","مكتبات وأدوات سطر الأوامر"]},"keywords":{"zh":["FFmpeg","多媒体处理","视频转码","音频处理","实时流媒体","命令行工具"],"ja":["FFmpeg","マルチメディア処理","ビデオ変換","オーディオ処理","リアルタイムストリーミング","コマンドラインツール"],"ko":["FFmpeg","멀티미디어 처리","비디오 변환","오디오 처리","실시간 스트리밍","명령줄 도구"],"es":["FFmpeg","multimedia","conversión de video","codificación de audio","transmisión en vivo","herramientas de línea de comandos","framework de código abierto","procesamiento de medios","formatos de archivo","codecs de video"],"fr":["FFmpeg","multimédia","conversion de vidéo","encodage d''audio","diffusion en direct","outils en ligne de commande","cadre open-source","traitement de médias","formats de fichiers","codecs de vidéo"],"de":["FFmpeg","Multimedia","Video-Konvertierung","Audio-Codierung","Live-Streaming","Kommandozeilen-Tools","Open-Source-Framework","Medienverarbeitung","Dateiformate","Video-Codecs"],"pt":["ffmpeg","processamento de multimídia","conversão de arquivos","codificação de vídeo","processamento de áudio","transmissão ao vivo","ferramentas de linha de comando"],"ru":["ffmpeg","обработка мультимедиа","конвертация файлов","кодирование видео","обработка аудио","прямая трансляция","инструменты командной строки"],"ar":["ffmpeg","معالجة الوسائط المتعددة","تحويل الملفات","ترميز الفيديو","معالجة الصوت","نقل مباشر","أدوات سطر الأوامر"]}},"owner":"huydepzai121","repo":"skill","repoPath":"huydepzai121/skill","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.404Z","topics":[],"category":"community","skillMd":{"name":"ffmpeg","description":"Guide for using FFmpeg - a comprehensive multimedia framework for video/audio encoding, conversion, streaming, and filtering. Use when processing media files, converting formats, extracting audio, creating streams, applying filters, or optimizing video/audio quality.","version":"1.0.0","bodyPreview":"# FFmpeg Skill\n\nFFmpeg is a comprehensive open-source multimedia framework that handles video, audio, and other multimedia files and streams. It provides command-line tools and libraries for recording, converting, and streaming audio and video.\n\n## When to Use This Skill\n\nUse this skill when:\n- Converting media files between formats (MP4, MKV, WebM, AVI, etc.)\n- Encoding/decoding video with different codecs (H.264, H.265, VP9, AV1)\n- Processing audio files (AAC, MP3, FLAC, Opus)\n- Live streaming","body":"# FFmpeg Skill\n\nFFmpeg is a comprehensive open-source multimedia framework that handles video, audio, and other multimedia files and streams. It provides command-line tools and libraries for recording, converting, and streaming audio and video.\n\n## When to Use This Skill\n\nUse this skill when:\n- Converting media files between formats (MP4, MKV, WebM, AVI, etc.)\n- Encoding/decoding video with different codecs (H.264, H.265, VP9, AV1)\n- Processing audio files (AAC, MP3, FLAC, Opus)\n- Live streaming to platforms (Twitch, YouTube, RTMP servers)\n- Creating HLS/DASH adaptive streams\n- Extracting audio from video files\n- Applying video/audio filters (scale, crop, denoise, volume)\n- Screen recording and capture\n- Optimizing video quality and file size\n- Batch processing media files\n- Analyzing media file properties\n\n## Core Components\n\n### Command-Line Tools\n\n**ffmpeg**: Primary tool for transcoding, conversion, and streaming\n**ffprobe**: Media analysis and inspection tool\n**ffplay**: Minimalist multimedia player for testing\n\n### Libraries\n\n- **libavcodec**: Encoding/decoding codecs\n- **libavformat**: Container formats and I/O\n- **libavfilter**: Audio/video filtering framework\n- **libavutil**: Utility functions\n- **libswscale**: Video scaling and color conversion\n- **libswresample**: Audio resampling and mixing\n\n## Common Video Codecs\n\n### Modern Codecs\n\n**H.264 (libx264)**: Most widely supported, excellent compression/quality balance\n- Best for: Universal compatibility, streaming, web video\n- Quality range: CRF 17-28 (lower = better quality)\n\n**H.265/HEVC (libx265)**: 25-50% better compression than H.264\n- Best for: 4K video, file size reduction\n- Slower encoding, limited browser support\n\n**VP9**: Royalty-free, WebM format\n- Best for: YouTube, open-source projects\n- Good quality/compression, Chrome/Firefox support\n\n**AV1 (libaom-av1, libsvtav1)**: Next-generation codec, best compression\n- Best for: Future-proofing, ultimate quality/size ratio\n- Very slow encoding (improving with SVT-AV1)\n\n### Legacy Codecs\n- MPEG-4 (Xvid/DivX)\n- MPEG-2\n- VP8\n\n## Common Audio Codecs\n\n**AAC**: Industry standard, excellent quality\n**MP3**: Universal compatibility, good quality\n**Opus**: Best quality at low bitrates, ideal for voice/streaming\n**FLAC**: Lossless compression, archival quality\n**Vorbis**: Open-source, good quality\n**AC-3/DTS**: Surround sound formats\n\n## Container Formats\n\n**MP4**: Universal compatibility, streaming-friendly\n**MKV (Matroska)**: Feature-rich, supports multiple tracks/subtitles\n**WebM**: Web-optimized (VP8/VP9 + Vorbis/Opus)\n**AVI**: Legacy format, broad compatibility\n**MOV**: Apple QuickTime format\n**TS**: Transport stream for broadcasting\n**FLV**: Flash video (legacy streaming)\n\n## Basic Operations\n\n### Format Conversion\n\nSimple format conversion without re-encoding:\n```bash\nffmpeg -i input.mkv -c copy output.mp4\n```\n\nConvert with specific codecs:\n```bash\nffmpeg -i input.avi -c:v libx264 -c:a aac output.mp4\n```\n\n### Quality-Based Encoding (CRF)\n\nConstant Rate Factor - best for quality-focused encoding:\n\n```bash\n# H.264 encoding (CRF 23 = default, 17-28 recommended range)\nffmpeg -i input.mkv -c:v libx264 -preset slow -crf 22 -c:a copy output.mp4\n\n# H.265 encoding (higher compression)\nffmpeg -i input.mkv -c:v libx265 -preset medium -crf 24 -c:a copy output.mp4\n\n# VP9 encoding (WebM)\nffmpeg -i input.mkv -c:v libvpx-vp9 -crf 30 -b:v 0 -c:a libopus output.webm\n```\n\n**CRF Scale:**\n- 0 = Lossless (huge file size)\n- 17-18 = Visually lossless\n- 20-23 = High quality (recommended)\n- 24-28 = Medium quality\n- 30+ = Low quality\n- 51 = Worst quality\n\n**Presets** (speed vs compression):\n- ultrafast, superfast, veryfast, faster, fast\n- medium (default)\n- slow, slower, veryslow (better compression)\n- placebo (not recommended - minimal gains)\n\n### Bitrate-Based Encoding (Two-Pass)\n\nFor targeting specific file sizes:\n\n```bash\n# Pass 1 (analysis)\nffmpeg -y -i input.mkv -c:v libx264 -b:v 2600k -pass 1 -an -f null /dev/null\n\n# Pass 2 (encoding)\nffmpeg -i input.mkv -c:v libx264 -b:v 2600k -pass 2 -c:a aac -b:a 128k output.mp4\n```\n\n### Audio Extraction\n\nExtract audio without re-encoding:\n```bash\nffmpeg -i video.mp4 -vn -c:a copy audio.m4a\n```\n\nExtract and convert to MP3:\n```bash\nffmpeg -i video.mp4 -vn -q:a 0 audio.mp3\n```\n\nExtract with specific bitrate:\n```bash\nffmpeg -i video.mp4 -vn -c:a libmp3lame -b:a 192k audio.mp3\n```\n\n### Video Scaling/Resizing\n\nScale to specific dimensions:\n```bash\nffmpeg -i input.mp4 -vf scale=1280:720 output.mp4\n```\n\nScale maintaining aspect ratio:\n```bash\n# Width 1280, height auto-calculated\nffmpeg -i input.mp4 -vf scale=1280:-1 output.mp4\n\n# Height 720, width auto-calculated\nffmpeg -i input.mp4 -vf scale=-1:720 output.mp4\n```\n\nScale to half resolution:\n```bash\nffmpeg -i input.mp4 -vf scale=iw/2:ih/2 output.mp4\n```\n\n### Trimming/Cutting Video\n\nCut without re-encoding (fast but less precise):\n```bash\nffmpeg -i input.mp4 -ss 00:01:30 -to 00:03:00 -c copy output.mp4\n```\n\nCut with re-encoding (precise):\n```bash\nffmpeg -i input.mp4 -ss 00:01:30 -t 00:01:30 -c:v libx264 -c:a aac output.mp4\n```\n\nParameters:\n- `-ss`: Start time (HH:MM:SS or seconds)\n- `-to`: End time\n- `-t`: Duration (instead of end time)\n\n### Concatenation\n\n**Method 1: Concat demuxer (same codec/format)**\n\nCreate `concat.txt`:\n```\nfile ''input1.mp4''\nfile ''input2.mp4''\nfile ''input3.mp4''\n```\n\nRun:\n```bash\nffmpeg -f concat -safe 0 -i concat.txt -c copy output.mp4\n```\n\n**Method 2: Concat filter (different formats)**\n```bash\nffmpeg -i input1.mp4 -i input2.mp4 -i input3.mp4 \\\n  -filter_complex \"[0:v][0:a][1:v][1:a][2:v][2:a]concat=n=3:v=1:a=1[v][a]\" \\\n  -map \"[v]\" -map \"[a]\" output.mp4\n```\n\n## Advanced Filtering\n\n### Video Filters\n\n**Multiple filters (chain with comma):**\n```bash\nffmpeg -i input.mp4 -vf \"scale=1280:720,hqdn3d\" output.mp4\n```\n\n**Denoise:**\n```bash\nffmpeg -i input.mp4 -vf hqdn3d output.mp4\n```\n\n**Deinterlace:**\n```bash\nffmpeg -i input.mp4 -vf yadif output.mp4\n```\n\n**Crop:**\n```bash\n# Crop to 1280x720 from top-left (0,0)\nffmpeg -i input.mp4 -vf \"crop=1280:720:0:0\" output.mp4\n\n# Auto-detect and remove black borders\nffmpeg -i input.mp4 -vf \"cropdetect\" output.mp4\n```\n\n**Rotate:**\n```bash\n# Rotate 90 degrees clockwise\nffmpeg -i input.mp4 -vf \"transpose=1\" output.mp4\n\n# Rotate 180 degrees\nffmpeg -i input.mp4 -vf \"transpose=1,transpose=1\" output.mp4\n```\n\n**Watermark/Logo:**\n```bash\nffmpeg -i video.mp4 -i logo.png \\\n  -filter_complex \"overlay=10:10\" output.mp4\n```\n\n**Speed adjustment:**\n```bash\n# 2x speed\nffmpeg -i input.mp4 -vf \"setpts=0.5*PTS\" -af \"atempo=2.0\" output.mp4\n\n# 0.5x speed (slow motion)\nffmpeg -i input.mp4 -vf \"setpts=2.0*PTS\" -af \"atempo=0.5\" output.mp4\n```\n\n### Audio Filters\n\n**Volume adjustment:**\n```bash\n# Increase volume by 10dB\nffmpeg -i input.mp4 -af \"volume=10dB\" output.mp4\n\n# Set to 50% volume\nffmpeg -i input.mp4 -af \"volume=0.5\" output.mp4\n```\n\n**Normalize audio:**\n```bash\nffmpeg -i input.mp4 -af loudnorm output.mp4\n```\n\n**Crossfade between audio:**\n```bash\nffmpeg -i audio1.mp3 -i audio2.mp3 \\\n  -filter_complex \"[0][1]acrossfade=d=5\" output.mp3\n```\n\n**Mix multiple audio tracks:**\n```bash\nffmpeg -i input1.mp3 -i input2.mp3 \\\n  -filter_complex \"[0:a][1:a]amix=inputs=2:duration=longest\" output.mp3\n```\n\n## Streaming\n\n### RTMP Streaming (Twitch/YouTube)\n\n**Basic stream:**\n```bash\nffmpeg -re -i input.mp4 -c:v libx264 -preset veryfast \\\n  -maxrate 3000k -bufsize 6000k -pix_fmt yuv420p -g 50 \\\n  -c:a aac -b:a 128k -ar 44100 \\\n  -f flv rtmp://live.twitch.tv/app/YOUR_STREAM_KEY\n```\n\n**Screen capture + stream (Linux):**\n```bash\nffmpeg -f x11grab -s 1920x1080 -framerate 30 -i :0.0 \\\n  -f pulse -ac 2 -i default \\\n  -c:v libx264 -preset veryfast -tune zerolatency \\\n  -maxrate 2500k -bufsize 5000k -pix_fmt yuv420p \\\n  -c:a aac -b:a 128k -ar 44100 \\\n  -f flv rtmp://live.twitch.tv/app/YOUR_STREAM_KEY\n```\n\n**Screen capture (Windows DirectShow):**\n```bash\nffmpeg -f dshow -i video=\"screen-capture-recorder\":audio=\"Stereo Mix\" \\\n  -c:v libx264 -preset ultrafast -tune zerolatency \\\n  -maxrate 750k -bufsize 3000k \\\n  -f flv rtmp://live.twitch.tv/app/YOUR_STREAM_KEY\n```\n\n**Important streaming parameters:**\n- `-re`: Read input at native frame rate (real-time)\n- `-tune zerolatency`: Optimize for low latency\n- `-g 50`: Keyframe every 50 frames (2 seconds @ 25fps)\n- `-maxrate`: Maximum bitrate\n- `-bufsize`: Rate control buffer (typically 2x maxrate)\n\n### HLS Streaming\n\nGenerate adaptive HLS stream:\n```bash\nffmpeg -i input.mp4 \\\n  -c:v libx264 -preset fast -crf 22 -g 48 -sc_threshold 0 \\\n  -c:a aac -b:a 128k \\\n  -f hls -hls_time 6 -hls_playlist_type vod \\\n  -hls_segment_filename \"segment_%03d.ts\" \\\n  playlist.m3u8\n```\n\n**Multi-bitrate HLS:**\n```bash\nffmpeg -i input.mp4 \\\n  -map 0:v -map 0:a -map 0:v -map 0:a \\\n  -c:v libx264 -crf 22 -c:a aac -b:a 128k \\\n  -b:v:0 2000k -s:v:0 1280x720 -b:v:1 5000k -s:v:1 1920x1080 \\\n  -var_stream_map \"v:0,a:0 v:1,a:1\" \\\n  -master_pl_name master.m3u8 \\\n  -f hls -hls_time 6 -hls_list_size 0 \\\n  stream_%v/index.m3u8\n```\n\n### UDP/RTP Streaming\n\n**UDP stream:**\n```bash\nffmpeg -re -i input.mp4 -c copy -f mpegts udp://192.168.1.100:1234\n```\n\n**RTP audio stream:**\n```bash\nffmpeg -re -i audio.mp3 -c:a libopus -f rtp rtp://192.168.1.100:5004\n```\n\n## Hardware Acceleration\n\n### NVIDIA NVENC\n\n```bash\n# H.264 with NVENC\nffmpeg -hwaccel cuda -i input.mp4 -c:v h264_nvenc -preset fast -crf 22 output.mp4\n\n# H.265 with NVENC\nffmpeg -hwaccel cuda -i input.mp4 -c:v hevc_nvenc -preset fast -crf 24 output.mp4\n```\n\n### Intel QuickSync (QSV)\n\n```bash\nffmpeg -hwaccel qsv -c:v h264_qsv -i input.mp4 \\\n  -c:v h264_qsv -preset fast -global_quality 22 output.mp4\n```\n\n### AMD VCE\n\n```bash\nffmpeg -hwaccel auto -i input.mp4 \\\n  -c:v h264_amf -quality balanced -rc cqp -qp 22 output.mp4\n```\n\n## Media Analysis\n\n### Inspect media file\n\n```bash\n# Detailed information\nffprobe -v quiet -print_format json -show_format -show_streams input.mp4\n\n# Human-readable format\nffprobe input.mp4\n\n# Get duration\nffprobe -v error -show_entries format=duration \\\n  -of default=noprint_wrappers=1:nokey=1 input.mp4\n\n# Get resolution\nffprobe -v error -select_streams v:0 \\\n  -show_entries stream=width,height \\\n  -of csv=s=x:p=0 input.mp4\n\n# Get bitrate\nffprobe -v error -show_entries format=bit_rate \\\n  -of default=noprint_wrappers=1:nokey=1 input.mp4\n```\n\n## Batch Processing\n\n### Bash loop for batch conversion\n\n```bash\n# Convert all MKV files to MP4\nfor file in *.mkv; do\n  ffmpeg -i \"$file\" -c:v libx264 -crf 22 -c:a aac \"${file%.mkv}.mp4\"\ndone\n\n# Resize all videos to 720p\nfor file in *.mp4; do\n  ffmpeg -i \"$file\" -vf scale=-1:720 \"720p_${file}\"\ndone\n```\n\n### Parallel processing with GNU Parallel\n\n```bash\n# Install: sudo apt-get install parallel\n\n# Process multiple files in parallel\nls *.mkv | parallel ffmpeg -i {} -c:v libx264 -crf 22 -c:a aac {.}.mp4\n```\n\n## Common Patterns\n\n### Create GIF from video\n\n```bash\n# High quality GIF\nffmpeg -i input.mp4 -vf \"fps=15,scale=640:-1:flags=lanczos,split[s0][s1];[s0]palettegen[p];[s1][p]paletteuse\" output.gif\n\n# Simple GIF\nffmpeg -i input.mp4 -vf \"fps=10,scale=320:-1\" output.gif\n```\n\n### Extract frames as images\n\n```bash\n# Extract all frames\nffmpeg -i input.mp4 frame_%04d.png\n\n# Extract 1 frame per second\nffmpeg -i input.mp4 -vf fps=1 frame_%04d.png\n\n# Extract single frame at 5 seconds\nffmpeg -ss 00:00:05 -i input.mp4 -frames:v 1 frame.png\n```\n\n### Create video from images\n\n```bash\n# From numbered images\nffmpeg -framerate 30 -i frame_%04d.png -c:v libx264 -crf 22 -pix_fmt yuv420p output.mp4\n\n# From pattern\nffmpeg -framerate 24 -pattern_type glob -i ''*.png'' -c:v libx264 output.mp4\n```\n\n### Add subtitles\n\n```bash\n# Burn subtitles into video\nffmpeg -i video.mp4 -vf subtitles=subtitles.srt output.mp4\n\n# Embed subtitle track (soft subtitles)\nffmpeg -i video.mp4 -i subtitles.srt -c copy -c:s mov_text output.mp4\n```\n\n### Remove audio\n\n```bash\nffmpeg -i input.mp4 -an -c:v copy output.mp4\n```\n\n### Replace audio\n\n```bash\nffmpeg -i video.mp4 -i audio.mp3 -c:v copy -c:a aac -map 0:v:0 -map 1:a:0 output.mp4\n```\n\n### Create thumbnail\n\n```bash\n# Single thumbnail at 5 seconds\nffmpeg -i input.mp4 -ss 00:00:05 -vframes 1 -vf scale=320:-1 thumb.jpg\n\n# Multiple thumbnails (one per minute)\nffmpeg -i input.mp4 -vf fps=1/60,scale=320:-1 thumb_%03d.jpg\n```\n\n## Performance Optimization\n\n### Speed vs Quality Trade-offs\n\n**Fast encoding (real-time processing):**\n```bash\nffmpeg -i input.mp4 -c:v libx264 -preset ultrafast -crf 23 output.mp4\n```\n\n**Balanced (default):**\n```bash\nffmpeg -i input.mp4 -c:v libx264 -preset medium -crf 22 output.mp4\n```\n\n**High quality (archival):**\n```bash\nffmpeg -i input.mp4 -c:v libx264 -preset veryslow -crf 18 output.mp4\n```\n\n### Multi-threading\n\nFFmpeg automatically uses multiple CPU cores. Override with:\n```bash\nffmpeg -threads 8 -i input.mp4 -c:v libx264 output.mp4\n```\n\n## Best Practices\n\n1. **Use CRF for quality-focused encoding** - Better than bitrate for most use cases\n2. **Two-pass for size targets** - When file size is critical\n3. **Copy streams when possible** - Use `-c copy` to avoid re-encoding\n4. **Choose appropriate presets** - Balance speed vs compression\n5. **Match output to source** - Don''t upscale or use higher quality than source\n6. **Test short clips first** - Verify settings before batch processing\n7. **Hardware acceleration** - Use GPU encoding for faster processing\n8. **Audio matters** - Don''t neglect audio codec/bitrate choices\n9. **Use filters efficiently** - Chain multiple filters with commas\n10. **Verify output** - Always check quality after encoding\n\n## Common Parameters Reference\n\n### Video Parameters\n- `-c:v` or `-vcodec`: Video codec\n- `-b:v`: Video bitrate (e.g., `2M`, `2500k`)\n- `-crf`: Constant Rate Factor (0-51)\n- `-preset`: Encoding speed/quality (ultrafast to veryslow)\n- `-tune`: Encoding optimization (film, animation, zerolatency)\n- `-pix_fmt`: Pixel format (yuv420p for compatibility)\n- `-r`: Frame rate (e.g., `30`, `60`)\n- `-g`: GOP size (keyframe interval)\n\n### Audio Parameters\n- `-c:a` or `-acodec`: Audio codec\n- `-b:a`: Audio bitrate (e.g., `128k`, `192k`)\n- `-ar`: Audio sample rate (e.g., `44100`, `48000`)\n- `-ac`: Audio channels (1=mono, 2=stereo)\n- `-q:a`: Audio quality for VBR (0=best for MP3)\n\n### General Parameters\n- `-i`: Input file\n- `-y`: Overwrite output without asking\n- `-n`: Never overwrite output\n- `-t`: Duration to encode\n- `-ss`: Start time offset\n- `-to`: End time\n- `-vf`: Video filters\n- `-af`: Audio filters\n- `-map`: Stream selection\n- `-metadata`: Set metadata\n- `-f`: Force format\n\n## Troubleshooting\n\n### \"Unknown encoder\" errors\nInstall codec libraries:\n```bash\n# Ubuntu/Debian\nsudo apt-get install ffmpeg libx264-dev libx265-dev libvpx-dev\n\n# Check available encoders\nffmpeg -encoders\n```\n\n### Output compatibility issues\nUse safe defaults for maximum compatibility:\n```bash\nffmpeg -i input.mkv -c:v libx264 -profile:v high -level 4.0 \\\n  -pix_fmt yuv420p -c:a aac -b:a 128k output.mp4\n```\n\n### Performance issues\n- Use hardware acceleration (`-hwaccel`)\n- Choose faster presets (`-preset fast`)\n- Reduce resolution with scale filter\n- Use multiple threads explicitly\n\n### Quality issues\n- Lower CRF value (18-22 for high quality)\n- Use slower preset (`-preset slow`)\n- Use two-pass encoding for better bitrate distribution\n- Match or exceed source bitrate\n\n## Resources\n\n- Official Documentation: https://ffmpeg.org/documentation.html\n- FFmpeg Wiki: https://trac.ffmpeg.org/\n- Codec Guides: https://trac.ffmpeg.org/wiki/Encode\n- Filter Documentation: https://ffmpeg.org/ffmpeg-filters.html\n- GitHub Repository: https://github.com/ffmpeg/ffmpeg\n- Community Examples: https://trac.ffmpeg.org/wiki/\n\n## Implementation Checklist\n\nWhen using FFmpeg:\n\n- [ ] Verify FFmpeg installation (`ffmpeg -version`)\n- [ ] Check available codecs for your use case\n- [ ] Test encoding settings on short clip first\n- [ ] Choose appropriate codec for target platform\n- [ ] Set quality level (CRF or bitrate)\n- [ ] Configure audio codec and bitrate\n- [ ] Apply necessary filters (scale, crop, etc.)\n- [ ] Consider hardware acceleration if available\n- [ ] Verify output quality and file size\n- [ ] Test output compatibility on target devices\n- [ ] Document settings for reproducibility\n- [ ] Create batch scripts for repetitive tasks\n"},"lastSynced":"2026-02-18T03:11:52.688Z","agentAnalysis":{"suitability":{"en":"Perfect for Media Processing Agents needing advanced video and audio conversion capabilities with FFmpeg","zh":"适用于需要高级视频和音频转换功能的媒体处理代理，支持FFmpeg","ja":"FFmpegを使用した高度なビデオおよびオーディオ変換機能を必要とするメディア処理エージェントに適しています","ko":"고급 비디오 및 오디오 변환 기능이 필요한 미디어 처리 에이전트에게 적합하며 FFmpeg를 지원합니다","es":"Perfecto para Agentes de Procesamiento de Medios que necesitan capacidades avanzadas de conversión de video y audio con FFmpeg","fr":"Parfait pour les Agents de Traitement des Médias ayant besoin de capacités avancées de conversion de vidéo et d''audio avec FFmpeg","de":"Perfekt für Medienverarbeitungsagenten, die erweiterte Video- und Audio-Konvertierungsfunktionen mit FFmpeg benötigen","pt":"Perfeito para Agentes de Processamento de Mídia que necessitam de capacidades avançadas de conversão de vídeo e áudio com FFmpeg","ru":"Идеально подходит для агентов обработки медиа, которым необходимы продвинутые возможности преобразования видео и аудио с помощью FFmpeg","ar":"مثالي للوكلاء معالجة الوسائط الذين يحتاجون إلى قدرات متقدمة لتحويل الفيديو والصوت مع FFmpeg"},"recommendation":{"en":"Empowers agents to convert media files between formats like MP4, MKV, and WebM, and to encode/decode video with codecs such as H.264, H.265, VP9, and AV1, while also processing audio files in formats like AAC, MP3, FLAC, and Opus for live streaming","zh":"赋予代理转换媒体文件之间的格式，如MP4、MKV和WebM，并使用H.264、H.265、VP9和AV1等编解码器编码/解码视频，同时处理AAC、MP3、FLAC和Opus等格式的音频文件以进行实时流媒体传输","ja":"エージェントに、MP4、MKV、WebMなどの形式間でメディアファイルを変換し、H.264、H.265、VP9、AV1などのコーデックを使用してビデオをエンコード/デコードし、AAC、MP3、FLAC、Opusなどの形式のオーディオファイルを処理してライブストリーミングを行う機能を提供する","ko":"에이전트가 MP4, MKV, WebM 등의 형식 간에 미디어 파일을 변환하고 H.264, H.265, VP9, AV1 등의 코덱을 사용하여 비디오를 인코딩/디코딩하며 AAC, MP3, FLAC, Opus 등의 형식의 오디오 파일을 처리하여 라이브 스트리밍을 수행할 수 있는 기능을 제공합니다","es":"Habilita a los agentes a convertir archivos de medios entre formatos como MP4, MKV y WebM, y a codificar/decodificar video con codecs como H.264, H.265, VP9 y AV1, así como procesar archivos de audio en formatos como AAC, MP3, FLAC y Opus para transmisiones en vivo","fr":"Permet aux agents de convertir des fichiers multimédias entre des formats tels que MP4, MKV et WebM, et de coder/décoder la vidéo avec des codecs tels que H.264, H.265, VP9 et AV1, tout en traitant les fichiers audio dans des formats tels que AAC, MP3, FLAC et Opus pour la diffusion en direct","de":"Ermöglicht es Agenten, Mediadateien zwischen Formaten wie MP4, MKV und WebM zu konvertieren und Video mit Codecs wie H.264, H.265, VP9 und AV1 zu kodieren/decodieren, sowie Audiodateien in Formaten wie AAC, MP3, FLAC und Opus für Live-Streaming zu verarbeiten","pt":"Habilita os agentes a converter arquivos de mídia entre formatos como MP4, MKV e WebM, e a codificar/decodificar vídeo com codecs como H.264, H.265, VP9 e AV1, além de processar arquivos de áudio em formatos como AAC, MP3, FLAC e Opus para transmissão ao vivo","ru":"Позволяет агентам конвертировать медиафайлы между форматами, такими как MP4, MKV и WebM, и кодировать/декодировать видео с помощью кодеков, таких как H.264, H.265, VP9 и AV1, а также обрабатывать аудиофайлы в форматах, таких как AAC, MP3, FLAC и Opus для прямой трансляции","ar":"تمكين الوكلاء من تحويل ملفات الوسائط بين صيغ مثل MP4 و MKV و WebM ، وتشفير / فك تشفير الفيديو باستخدام محدّدات مثل H.264 و H.265 و VP9 و AV1 ، بالإضافة إلى معالجة ملفات الصوت بصيغ مثل AAC و MP3 و FLAC و Opus لنقل مباشر"},"useCases":{"en":["Converting video files for cross-platform compatibility","Encoding audio files for efficient live streaming","Processing multimedia files for web-based applications"],"zh":["为跨平台兼容性转换视频文件","为高效的实时流媒体编码音频文件","为基于Web的应用程序处理多媒体文件"],"ja":["クロスプラットフォーム互換性のためにビデオファイルを変換する","効率的なライブストリーミングのためにオーディオファイルをエンコードする","ウェブベースのアプリケーション用にマルチメディアファイルを処理する"],"ko":["크로스 플랫폼 호환성을 위해 비디오 파일을 변환하는 것","효율적인 라이브 스트리밍을 위해 오디오 파일을 인코딩하는 것","웹 기반 애플리케이션을 위한 멀티미디어 파일 처리"],"es":["Conversión de archivos de video para compatibilidad entre plataformas","Codificación de archivos de audio para una transmisión en vivo eficiente","Procesamiento de archivos multimedia para aplicaciones web"],"fr":["Conversion de fichiers vidéo pour la compatibilité entre plates-formes","Codage de fichiers audio pour une diffusion en direct efficace","Traitement de fichiers multimédias pour les applications web"],"de":["Konvertierung von Videodateien für Plattformübergreifende Kompatibilität","Kodierung von Audiodateien für effizientes Live-Streaming","Verarbeitung von Multimediadateien für webbasierte Anwendungen"],"pt":["Conversão de arquivos de vídeo para compatibilidade entre plataformas","Codificação de arquivos de áudio para transmissão ao vivo eficiente","Processamento de arquivos multimídia para aplicações baseadas na web"],"ru":["Преобразование видеофайлов для совместимости на разных платформах","Кодирование аудиофайлов для эффективной прямой трансляции","Обработка мультимедийных файлов для веб-приложений"],"ar":["تحويل ملفات الفيديو لتحقيق التوافق بين المنصات","تشفير ملفات الصوت لنقل مباشر فعال","معالجة ملفات الوسائط المتعددة لتطبيقات الويب"]},"limitations":{"en":["Requires command-line interface access","Dependent on system libraries and codecs"],"zh":["需要命令行接口访问","依赖于系统库和编解码器"],"ja":["コマンドラインインターフェースへのアクセスが必要","システムライブラリおよびコーデックに依存する"],"ko":["명령줄 인터페이스에 대한 액세스가 필요함","시스템 라이브러리 및 코덱에 의존"],"es":["Requiere acceso a la interfaz de línea de comandos","Dependiente de bibliotecas y codecs del sistema"],"fr":["Nécessite un accès à l''interface de ligne de commande","Dépend des bibliothèques et des codecs du système"],"de":["Benötigt Zugriff auf die Kommandozeilenoberfläche","Abhängig von Systembibliotheken und Codecs"],"pt":["Requer acesso à interface de linha de comando","Dependente de bibliotecas e codecs do sistema"],"ru":["Требует доступа к командной строке","Зависит от системных библиотек и кодеков"],"ar":["يتطلب الوصول إلى واجهة سطر الأوامر","يعتمد على مكتبات الوكلاء والكوديكات"]},"version":3},"qualityScore":75}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sylin-org/koan-framework/koan-performance', 'community', 'sylin-org', 'koan-framework', 'sylin-org/koan-framework', 'koan-performance', 0, 0, 40, '2026-02-18T01:08:43.404Z', '2026-02-18T03:11:56.769Z', NULL, '{"id":"sylin-org/koan-framework/koan-performance","name":"koan-performance","description":{"zh":"Koan是一个现代的、模块化的.NET 10框架，旨在帮助小团队构建复杂应用。它提供了实体优先的持久化、多提供者透明性、AI集成和事件驱动的架构等特点","ja":"Koanは、小規模チームが複雑なアプリケーションを構築できるように設計された、モダンでモジュール化された.NET 10フレームワークです。エンティティ優先の永続化、複数プロバイダーの透過性、AI統合、イベントドリブンのアーキテクチャなどの特徴を提供します","ko":"코안은 소규모 팀이 복잡한 애플리케이션을 구축할 수 있도록 설계된 현대적이고 모듈화된 .NET 10 프레임워크입니다. 엔티티 우선의 지속성, 다중 공급자 투명성, AI 통합 및 이벤트 주도 아키텍처 등의 특징을 제공","es":"Koan es un framework .NET 10 modular que permite a los equipos pequeños construir aplicaciones sofisticadas con patrones simples. Optimiza para escalabilidad desde el primer día.","fr":"Koan est un framework .NET 10 modulaire qui permet aux petits équipes de construire des applications sophistiquées avec des modèles simples. Optimisez pour l''évolutivité dès le premier jour.","de":"Koan ist ein modulares .NET 10-Framework, das es kleinen Teams ermöglicht, komplexe Anwendungen mit einfachen Mustern zu erstellen. Optimieren Sie für Skalierbarkeit von Tag eins an.","pt":"Koan é um framework .NET 10 modular que ajuda a construir aplicações sofisticadas com padrões simples. Otimização para escala desde o início.","ru":"Koan - это модульный фреймворк .NET 10, предназначенный для создания сложных приложений с простыми шаблонами. Оптимизация для масштаба с первого дня.","ar":"كوان هو إطار عمل .NET 10 قابل للتحديث مصمم لإنشاء تطبيقات متقدمة باستخدام أنماط بسيطة. تحسين الأداء للنطاق منذ البداية.","en":"Koan is a modern, modular .NET 10 framework designed to make small teams capable of building sophisticated applications with simple patterns. Entity-first persistence, multi-provider transparency, AI integration, event-driven architecture with zero configuration ceremony."},"seo":{"title":{"zh":"Koan性能优化框架","ja":"Koanパフォーマンス最適化フレームワーク","ko":"코안 성능 최적화 프레임워크","es":"Koan Performance: Optimización para Escalabilidad","fr":"Koan Performance: Optimisation pour l''évolutivité","de":"Koan Performance: Optimierung für Skalierbarkeit","pt":"Koan Performance: Otimização de Escala","ru":"Koan Performance: Оптимизация Масштаба","ar":"كوان للأداء: تحسين القدرة على التوسع","en":"koan-performance"},"description":{"zh":"Koan是一个现代的、模块化的.NET 10框架，旨在帮助小团队构建复杂应用。它提供了实体优先的持久化、多提供者透明性、AI集成和事件驱动的架构等特点","ja":"Koanは、小規模チームが複雑なアプリケーションを構築できるように設計された、モダンでモジュール化された.NET 10フレームワークです。エンティティ優先の永続化、複数プロバイダーの透過性、AI統合、イベントドリブンのアーキテクチャなどの特徴を提供します","ko":"코안은 소규모 팀이 복잡한 애플리케이션을 구축할 수 있도록 설계된 현대적이고 모듈화된 .NET 10 프레임워크입니다. 엔티티 우선의 지속성, 다중 공급자 투명성, AI 통합 및 이벤트 주도 아키텍처 등의 특징을 제공","es":"Koan es un framework .NET 10 modular que permite a los equipos pequeños construir aplicaciones sofisticadas con patrones simples. Optimiza para escalabilidad...","fr":"Koan est un framework .NET 10 modulaire qui permet aux petits équipes de construire des applications sophistiquées avec des modèles simples. Optimisez pour l...","de":"Koan ist ein modulares .NET 10-Framework, das es kleinen Teams ermöglicht, komplexe Anwendungen mit einfachen Mustern zu erstellen. Optimieren Sie für Skalie...","pt":"Koan é um framework .NET 10 modular que ajuda a construir aplicações sofisticadas com padrões simples. Otimização para escala desde o início.","ru":"Koan - это модульный фреймворк .NET 10, предназначенный для создания сложных приложений с простыми шаблонами. Оптимизация для масштаба с первого дня.","ar":"كوان هو إطار عمل .NET 10 قابل للتحديث مصمم لإنشاء تطبيقات متقدمة باستخدام أنماط بسيطة. تحسين الأداء للنطاق منذ البداية.","en":"Koan is a modern, modular .NET 10 framework designed to make small teams capable of building sophisticated applications with simple patterns. Entity-first pe..."},"definition":{"en":"Koan is a modern, modular .NET 10 framework designed to make small teams capable of building sophisticated applications with simple patterns. Entity-first persistence, multi-provider transparency, AI integration, event-driven architecture with zero configuration ceremony."},"features":{"zh":["实体优先的持久化","多提供者透明性","AI集成","事件驱动的架构","流式处理大数据集","批量操作"],"ja":["エンティティ優先の永続化","複数プロバイダーの透過性","AI統合","イベントドリブンのアーキテクチャ","ストリーミングによる大規模データセットの処理","バッチ操作"],"ko":["엔티티 우선의 지속성","다중 공급자 투명성","AI 통합","이벤트 주도 아키텍처","스트리밍을 통한 대규모 데이터셋 처리","배치 작업"],"es":["Streaming para grandes conjuntos de datos","Operaciones por lotes para cambios masivos","Recuentos rápidos para interfaces de usuario","Paginación para APIs web"],"fr":["Streaming pour les grands ensembles de données","Opérations par lots pour les modifications massives","Comptages rapides pour les interfaces utilisateur","Pagination pour les API web"],"de":["Streaming für große Datensätze","Batch-Operationen für Massenänderungen","Schnelle Zählungen für Benutzeroberflächen","Paginierung für Web-APIs"],"pt":["Otimização para escala desde o início","Transparência de provedor múltiplo","Integração de IA","Arquitetura orientada a eventos com zero configuração","Processamento em lote para alterações em massa","Contagens rápidas para UI"],"ru":["Оптимизация для масштаба с первого дня","Прозрачность нескольких поставщиков","Интеграция ИИ","Архитектура, ориентированная на события, с нулевой конфигурацией","Пакетная обработка для массовых изменений","Быстрые подсчеты для UI"],"ar":["تحسين الأداء للنطاق منذ البداية","شفافية مزود متعدد","تكامل الذكاء الاصطناعي","هندسة معمارية مدفوعة بالحدث مع تكوين صفر","معالجة الدفعة لتحديثات كبيرة","عدّ سريع للواجهة المستخدمة"]},"keywords":{"zh":["Koan性能优化","NET 10框架","实体优先的持久化","多提供者透明性","AI集成","事件驱动的架构","流式处理大数据集"],"ja":["Koanパフォーマンス最適化","NET 10フレームワーク","エンティティ優先の永続化","複数プロバイダーの透過性","AI統合","イベントドリブンのアーキテクチャ","ストリーミングによる大規模データセットの処理"],"ko":["코안 성능 최적화","NET 10 프레임워크","엔티티 우선의 지속성","다중 공급자 투명성","AI 통합","이벤트 주도 아키텍처","스트리밍을 통한 대규모 데이터셋 처리"],"es":["Koan performance","optimización para escalabilidad","framework .NET 10","patrones de streaming","aplicaciones sofisticadas","equipos pequeños","desarrollo de software"],"fr":["Koan performance","optimisation pour l''évolutivité","framework .NET 10","modèles de streaming","applications sophistiquées","petits équipes","développement de logiciels"],"de":["Koan Performance","Optimierung für Skalierbarkeit","Framework .NET 10","Streaming-Muster","komplexe Anwendungen","kleine Teams","Softwareentwicklung"],"pt":["Koan Performance","Otimização de escala","Desempenho de aplicativos","Framework .NET 10","Arquitetura orientada a eventos","Integração de IA","Transparência de provedor múltiplo","Processamento em lote","Contagens rápidas"],"ru":["Koan Performance","Оптимизация масштаба","Производительность приложений","Фреймворк .NET 10","Архитектура, ориентированная на события","Интеграция ИИ","Прозрачность нескольких поставщиков","Пакетная обработка","Быстрые подсчеты"],"ar":["كوان للأداء","تحسين القدرة على التوسع","أداء التطبيقات","إطار عمل .NET 10","هندسة معمارية مدفوعة بالحدث","تكامل الذكاء الاصطناعي","شفافية مزود متعدد","معالجة الدفعة","عدّ سريع"]}},"owner":"sylin-org","repo":"koan-framework","repoPath":"sylin-org/koan-framework","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.404Z","topics":[],"category":"community","skillMd":{"name":"koan-performance","description":"Streaming, pagination, count strategies, bulk operations","bodyPreview":"# Koan Performance\n\n## Core Principle\n\n**Optimize for scale from day one.** Use streaming for large datasets, batch operations for bulk changes, fast counts for UI, and pagination for web APIs.\n\n## Performance Patterns\n\n### Streaming (Large Datasets)\n\n```csharp\n// ❌ WRONG: Load everything into memory\nvar allTodos = await Todo.All(); // 1 million records!\n\n// ✅ CORRECT: Stream in batches\nawait foreach (var todo in Todo.AllStream(batchSize: 1000))\n{\n    await ProcessTodo(todo);\n}\n```\n\n### Count St","body":"# Koan Performance\n\n## Core Principle\n\n**Optimize for scale from day one.** Use streaming for large datasets, batch operations for bulk changes, fast counts for UI, and pagination for web APIs.\n\n## Performance Patterns\n\n### Streaming (Large Datasets)\n\n```csharp\n// ❌ WRONG: Load everything into memory\nvar allTodos = await Todo.All(); // 1 million records!\n\n// ✅ CORRECT: Stream in batches\nawait foreach (var todo in Todo.AllStream(batchSize: 1000))\n{\n    await ProcessTodo(todo);\n}\n```\n\n### Count Strategies\n\n```csharp\n// Fast count (metadata estimate - 1000x+ faster)\nvar fast = await Todo.Count.Fast(ct); // ~5ms for 10M rows\n\n// Exact count (guaranteed accuracy)\nvar exact = await Todo.Count.Exact(ct); // ~25s for 10M rows\n\n// Optimized (framework chooses)\nvar optimized = await Todo.Count; // Uses Fast if available\n```\n\n**Use Fast for:** Pagination UI, dashboards, estimates\n**Use Exact for:** Critical business logic, reports, inventory\n\n### Bulk Operations\n\n```csharp\n// Bulk create\nvar todos = Enumerable.Range(1, 1000)\n    .Select(i => new Todo { Title = $\"Task {i}\" })\n    .ToList();\nawait todos.Save(); // Single operation\n\n// Bulk removal\nawait Todo.RemoveAll(RemoveStrategy.Fast); // TRUNCATE/DROP (225x faster)\n```\n\n### Batch Retrieval\n\n```csharp\n// ❌ WRONG: N queries\nforeach (var id in ids)\n{\n    var todo = await Todo.Get(id);\n}\n\n// ✅ CORRECT: 1 query\nvar todos = await Todo.Get(ids);\n```\n\n### Pagination\n\n```csharp\npublic async Task<IActionResult> GetTodos(\n    int page = 1,\n    int pageSize = 20,\n    CancellationToken ct = default)\n{\n    var result = await Todo.QueryWithCount(\n        t => !t.Completed,\n        new DataQueryOptions { OrderBy = nameof(Todo.Created), Descending = true },\n        ct);\n\n    Response.Headers[\"X-Total-Count\"] = result.TotalCount.ToString();\n    return Ok(result.Items);\n}\n```\n\n## Performance Benchmarks\n\n| Operation | Inefficient | Efficient | Speedup |\n|-----------|-------------|-----------|---------|\n| **Bulk Remove (1M)** | DELETE loop ~45s | TRUNCATE ~200ms | 225x |\n| **Count (10M)** | Full scan ~25s | Metadata ~5ms | 5000x |\n| **Batch Get (100)** | 100 queries | 1 query | 100x |\n| **Stream (1M)** | Load all (OOM) | Stream batches | Memory safe |\n\n## When This Skill Applies\n\n- ✅ Performance tuning\n- ✅ Large datasets\n- ✅ Optimization\n- ✅ Production readiness\n- ✅ Memory issues\n- ✅ Query optimization\n\n## Reference Documentation\n\n- **Example Code:** `.claude/skills/entity-first/examples/batch-operations.cs`\n- **Guide:** `docs/guides/performance.md`\n- **Sample:** `samples/S14.AdapterBench/` (Performance benchmarks)\n"},"lastSynced":"2026-02-18T03:11:56.769Z","agentAnalysis":{"suitability":{"en":"Perfect for .NET Agents needing high-performance data processing with streaming and pagination capabilities.","zh":"非常适合需要高性能数据处理的 .NET Agents，具有流媒体和分页功能。","ja":".NET エージェントが高パフォーマンスのデータ処理とストリーミングおよびページネーション機能を必要とする場合に最適です。","ko":".NET 에이전트가 높은 성능의 데이터 처리와 스트리밍 및 페이징 기능을 필요로 할 경우 적합합니다.","es":"Perfecto para agentes .NET que necesitan procesamiento de datos de alto rendimiento con capacidades de transmisión y paginación.","fr":"Parfait pour les agents .NET nécessitant un traitement de données haute performance avec des capacités de diffusion en continu et de pagination.","de":"Perfekt für .NET-Agents, die ein hochleistungsloses Datenverarbeiten mit Streaming- und Paginierungsfunktionen benötigen.","pt":"Perfeito para agentes .NET que precisam de processamento de dados de alto desempenho com recursos de transmissão e paginação.","ru":"Идеально подходит для агентов .NET, которым требуется высокопроизводительная обработка данных с возможностями потоковой передачи и постраничной навигации.","ar":"مثالي لعميل .NET الذي يحتاج إلى معالجة بيانات عالية الأداء مع إمكانيات البث والتنقّل بين الصفحات."},"recommendation":{"en":"Empowers agents to optimize data retrieval and manipulation using entity-first persistence, multi-provider transparency, and event-driven architecture, ensuring scalable applications from day one with features like streaming for large datasets and batch operations for bulk changes.","zh":"赋予代理优化数据检索和操作的能力，使用实体优先的持久性、多提供商透明度和事件驱动的体系结构，确保从第一天开始具有可扩展的应用程序，具有流媒体处理大型数据集和批处理操作的大量更改等功能。","ja":"エージェントにデータの取得と操作を最適化する能力を付与し、エンティティ優先の永続性、複数プロバイダーの透明性、およびイベント駆動型アーキテクチャを使用して、ストリーミングによる大規模データセットの処理やバッチ操作による大量の変更などの機能を備えた、最初の日からスケーラブルなアプリケーションを保証します。","ko":"대리인이 데이터 검색 및 조작을 최적화 할 수 있는 능력을 부여하여 엔티티 우선의 지속성, 다중 공급자 투명성 및 이벤트 주도 아키텍처를 사용하여 대규모 데이터 세트에 대한 스트리밍 및 대량 변경에 대한 배치 작업과 같은 기능으로 처음부터 확장 가능한 애플리케이션을 보장합니다.","es":"Habilita a los agentes a optimizar la recuperación y manipulación de datos utilizando la persistencia de entidad primero, la transparencia de multi-proveedor y la arquitectura orientada a eventos, garantizando aplicaciones escalables desde el primer día con características como la transmisión para grandes conjuntos de datos y operaciones por lotes para cambios masivos.","fr":"Permet aux agents d''optimiser la récupération et la manipulation des données en utilisant la persistance d''entité première, la transparence multi-fournisseur et l''architecture orientée événement, garantissant des applications évolutives dès le premier jour avec des fonctionnalités telles que le streaming pour les grands ensembles de données et les opérations par lots pour les modifications massives.","de":"Ermöglicht es den Agents, die Datenerfassung und -manipulation zu optimieren, indem sie die Entity-First-Persistenz, die Multi-Anbieter-Transparenz und die ereignisgesteuerte Architektur verwenden, um skalierbare Anwendungen von Tag eins an zu gewährleisten, mit Funktionen wie Streaming für große Datensätze und Batch-Operationen für Massenänderungen.","pt":"Permite que os agentes otimizem a recuperação e manipulação de dados usando persistência de entidade em primeiro lugar, transparência de vários provedores e arquitetura orientada a eventos, garantindo aplicações escaláveis desde o início com recursos como transmissão para grandes conjuntos de dados e operações em lote para alterações em massa.","ru":"Позволяет агентам оптимизировать извлечение и обработку данных, используя подход сначала сущность, прозрачность нескольких поставщиков и событийно-ориентированную архитектуру, обеспечивая масштабируемые приложения с первого дня с функциями, такими как потоковая передача для больших наборов данных и пакетные операции для массовых изменений.","ar":"تمكّن العميل من تحسين استرجاع البيانات وتنقيحها باستخدام استمرار الكيان أولاً، وشفافية مزود متعدّد، وهندسة مدفوعة بالأحداث، مما يضمن تطبيقات قابلة للتوسّع منذ البداية مع ميزات مثل البثّ لنطاقات البيانات الكبيرة، وعمليات المجموعة للتغييرات الضخمة."},"useCases":{"en":["Streaming large datasets for efficient data processing","Implementing pagination for web APIs to reduce data transfer","Optimizing database queries using fast counts for UI updates"],"zh":["为高效数据处理而流式传输大型数据集","为 Web API 实现分页以减少数据传输","使用快速计数优化数据库查询以进行 UI 更新"],"ja":["効率的なデータ処理のための大規模データセットのストリーミング","Web API でのページネーションの実装によるデータ転送の削減","高速カウントを使用したデータベースクエリの最適化による UI 更新"],"ko":["효율적인 데이터 처리를 위한 대규모 데이터 세트의 스트리밍","웹 API에서 페이지네이션을 구현하여 데이터 전송을 줄임","빠른 카운트를 사용하여 데이터베이스 쿼리를 최적화하여 UI 업데이트를 수행"],"es":["Transmisión de grandes conjuntos de datos para un procesamiento de datos eficiente","Implementación de la paginación para APIs web para reducir la transferencia de datos","Optimización de consultas de base de datos utilizando recuentos rápidos para actualizaciones de la interfaz de usuario"],"fr":["Diffusion en continu de grands ensembles de données pour un traitement de données efficace","Mise en œuvre de la pagination pour les API Web pour réduire le transfert de données","Optimisation des requêtes de base de données en utilisant des décomptes rapides pour les mises à jour de l''interface utilisateur"],"de":["Streaming großer Datensätze für effizientes Datenverarbeiten","Implementierung der Paginierung für Web-APIs, um den Datentransfer zu reduzieren","Optimierung von Datenbankabfragen unter Verwendung von schnellen Zählungen für Benutzeroberflächen-Aktualisierungen"],"pt":["Transmissão de grandes conjuntos de dados para processamento de dados eficiente","Implementação de paginação para APIs da web para reduzir a transferência de dados","Otimização de consultas de banco de dados usando contagens rápidas para atualizações de UI"],"ru":["Потоковая передача больших наборов данных для эффективной обработки данных","Реализация постраничной навигации для веб-API для уменьшения передачи данных","Оптимизация запросов к базе данных с помощью быстрых счетчиков для обновления UI"],"ar":["بثّ نطاقات بيانات كبيرة للتحليل الفعّال للبيانات","تنفيذ التنقّل بين الصفحات لبروتوكولات الويب لتقليل نقل البيانات","تحسين استفسارات قاعدة البيانات باستخدام العدّ السريع لإعادة تعيين الواجهة"]},"limitations":{"en":[".NET 10 framework required","Limited to entity-first persistence approach"],"zh":[".NET 10 框架是必需的","仅限于实体优先的持久性方法"],"ja":[".NET 10 フレームワークが必要","エンティティ優先の永続性アプローチに限定"],"ko":[".NET 10 프레임워크가 필요","엔티티 우선의 지속성 접근 방식으로 제한"],"es":[".NET 10 framework requerido","Limitado al enfoque de persistencia de entidad primero"],"fr":[".NET 10 framework requis","Limité à l''approche de persistance d''entité première"],"de":[".NET 10-Framework erforderlich","Begrenzt auf den Entity-First-Persistenzansatz"],"pt":[".NET 10 framework necessário","Limitado ao método de persistência de entidade em primeiro lugar"],"ru":["Требуется платформа .NET 10","Ограничен подходом сначала сущность"],"ar":["إطار .NET 10 مطلوب","محدود بنهج استمرار الكيان أولاً"]},"version":3},"qualityScore":40}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('natea/fitfinder/threejs-game', 'community', 'natea', 'fitfinder', 'natea/fitfinder', 'threejs-game', 0, 0, 75, '2026-02-18T01:08:43.404Z', '2026-02-18T03:12:13.865Z', NULL, '{"id":"natea/fitfinder/threejs-game","name":"threejs-game","description":{"zh":"Three.js, WebGL, 3D","ja":"Three.js, WebGL, 3D","ko":"Three.js, WebGL, 3D","es":"Asistencia integral para el desarrollo de juegos con Three.js, incluyendo renderizado 3D, mecánicas de juego y física.","fr":"Assistance complète pour le développement de jeux avec Three.js, incluant le rendu 3D, les mécaniques de jeu et la physique.","de":"Umfassende Unterstützung für die Entwicklung von Spielen mit Three.js, einschließlich 3D-Rendering, Spielmechanik und Physik.","pt":"Three.js é uma biblioteca JavaScript para criar jogos 3D no navegador. Fornece assistência abrangente para desenvolvimento de jogos com WebGL.","ru":"Three.js — это библиотека JavaScript для создания 3D-игр в браузере. Предоставляет всестороннюю помощь в разработке игр с помощью WebGL.","ar":"Three.js هي مكتبة جافاسكريبت لإنشاء ألعاب 3D في المتصفح. توفر مساعدة شاملة لتطوير الألعاب باستخدام WebGL.","en":"AI agents help accelerate product/market fit. Discover what to build and who to build it for."},"seo":{"title":{"zh":"Three.js ","ja":"Three.js","ko":"Three.js ","es":"Desarrollo de Juegos con Three.js","fr":"Développement de Jeux avec Three.js","de":"Three.js-Spiel-Entwicklung","pt":"Desenvolvimento de Jogos com Three.js","ru":"Разработка игр с Three.js","ar":"تطوير الألعاب باستخدام Three.js","en":"threejs-game"},"description":{"zh":"Three.js, WebGL, 3D","ja":"Three.js, WebGL, 3D","ko":"Three.js, WebGL, 3D","es":"Asistencia integral para el desarrollo de juegos con Three.js, incluyendo renderizado 3D, mecánicas de juego y física.","fr":"Assistance complète pour le développement de jeux avec Three.js, incluant le rendu 3D, les mécaniques de jeu et la physique.","de":"Umfassende Unterstützung für die Entwicklung von Spielen mit Three.js, einschließlich 3D-Rendering, Spielmechanik und Physik.","pt":"Three.js é uma biblioteca JavaScript para criar jogos 3D no navegador. Fornece assistência abrangente para desenvolvimento de jogos com WebGL.","ru":"Three.js — это библиотека JavaScript для создания 3D-игр в браузере. Предоставляет всестороннюю помощь в разработке игр с помощью WebGL.","ar":"Three.js هي مكتبة جافاسكريبت لإنشاء ألعاب 3D في المتصفح. توفر مساعدة شاملة لتطوير الألعاب باستخدام WebGL.","en":"AI agents help accelerate product/market fit. Discover what to build and who to build it for."},"definition":{"en":"AI agents help accelerate product/market fit. Discover what to build and who to build it for."},"features":{"zh":["Three.js","WebGL","3D","","GLTF, OBJ, FBX",""],"ja":["Three.js","WebGL","3D","","GLTF, OBJ, FBX",""],"ko":["Three.js","WebGL","3D","","GLTF, OBJ, FBX",""],"es":["Renderizado 3D con WebGL","Implementación de mecánicas de juego","Carga de modelos 3D","Manejo de entradas de usuario","Creación de juegos interactivos en el navegador","Gestión de cámaras y luces"],"fr":["Rendu 3D avec WebGL","Mise en œuvre de mécaniques de jeu","Chargement de modèles 3D","Gestion des entrées utilisateur","Création de jeux interactifs dans le navigateur","Gestion des caméras et des lumières"],"de":["3D-Rendering mit WebGL","Implementierung von Spielmechaniken","Laden von 3D-Modellen","Verarbeitung von Benutzereingaben","Erstellung interaktiver Spiele im Browser","Verwaltung von Kameras und Licht"],"pt":["Desenvolvimento de jogos 3D no navegador","Renderização 3D com WebGL","Mecânicas de jogo e física","Animações e efeitos visuais","Câmeras, iluminação e gerenciamento de cena"],"ru":["Разработка 3D-игр в браузере","3D-рендеринг с помощью WebGL","Игровая механика и физика","Анимации и визуальные эффекты","Камеры, освещение и управление сценой"],"ar":["تطوير الألعاب 3D في المتصفح","ترndering 3D باستخدام WebGL","ميكانيكا اللعبة والفيزياء","الرسومات المتحركة والتأثيرات البصرية","الكاميرات والإضاءة وإدارة المشهد"]},"keywords":{"zh":["Three.js","WebGL","3D","Three.js","Web","GLTF","OBJ","FBX",""],"ja":["Three.js","WebGL","3D","Three.js","Web","GLTF","OBJ","FBX",""],"ko":["Three.js","WebGL","3D","Three.js","Web","GLTF","OBJ","FBX",""],"es":["desarrollo de juegos","Three.js","WebGL","renderizado 3D","mecánicas de juego","física","juegos web","experiencias 3D","JavaScript"],"fr":["développement de jeux","Three.js","WebGL","rendu 3D","mécaniques de jeu","physique","jeux web","expériences 3D","JavaScript"],"de":["Spiel-Entwicklung","Three.js","WebGL","3D-Rendering","Spielmechaniken","Physik","Web-Spiele","3D-Erfahrungen","JavaScript"],"pt":["Three.js","Desenvolvimento de jogos 3D","WebGL","Renderização 3D","Mecânicas de jogo","Física","Animações","Efeitos visuais"],"ru":["Three.js","Разработка 3D-игр","WebGL","3D-рендеринг","Игровая механика","Физика","Анимации","Визуальные эффекты"],"ar":["Three.js","تطوير الألعاب 3D","WebGL","ترndering 3D","ميكانيكا اللعبة","الفيزياء","الرسومات المتحركة","التأثيرات البصرية"]}},"owner":"natea","repo":"fitfinder","repoPath":"natea/fitfinder","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.404Z","topics":[],"category":"community","skillMd":{"name":"threejs-game","description":"Three.js game development. Use for 3D web games, WebGL rendering, game mechanics, physics integration, character controllers, camera systems, lighting, animations, and interactive 3D experiences in the browser.","bodyPreview":"# Three.js Game Development Skill\n\nComprehensive assistance with Three.js game development using WebGL, covering 3D rendering, game mechanics, physics, animations, and interactive browser-based games.\n\n## When to Use This Skill\n\nActivate this skill when:\n- Building 3D web games with Three.js\n- Implementing game mechanics (player movement, collisions, scoring)\n- Setting up cameras, lighting, and scene management\n- Loading 3D models (GLTF, OBJ, FBX)\n- Handling user input (keyboard, mouse, touch, g","body":"# Three.js Game Development Skill\n\nComprehensive assistance with Three.js game development using WebGL, covering 3D rendering, game mechanics, physics, animations, and interactive browser-based games.\n\n## When to Use This Skill\n\nActivate this skill when:\n- Building 3D web games with Three.js\n- Implementing game mechanics (player movement, collisions, scoring)\n- Setting up cameras, lighting, and scene management\n- Loading 3D models (GLTF, OBJ, FBX)\n- Handling user input (keyboard, mouse, touch, gamepad)\n- Creating animations and character controllers\n- Integrating physics engines (Cannon.js, Ammo.js)\n- Optimizing 3D game performance\n- Working with shaders and materials for game visuals\n\n## Quick Reference\n\n### Basic Game Setup\n\n```javascript\nimport * as THREE from ''three'';\n\n// Create scene, camera, renderer\nconst scene = new THREE.Scene();\nconst camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);\nconst renderer = new THREE.WebGLRenderer({ antialias: true });\nrenderer.setSize(window.innerWidth, window.innerHeight);\ndocument.body.appendChild(renderer.domElement);\n\n// Game loop\nfunction animate(time) {\n  requestAnimationFrame(animate);\n\n  // Update game logic here\n  updatePlayer(time);\n  updateEnemies(time);\n  checkCollisions();\n\n  renderer.render(scene, camera);\n}\n\nanimate();\n```\n\n### Player Controller (Third-Person)\n\n```javascript\nclass PlayerController {\n  constructor(camera, target) {\n    this.camera = camera;\n    this.target = target;\n    this.distance = 10;\n    this.height = 5;\n    this.rotationSpeed = 0.005;\n    this.moveSpeed = 0.1;\n  }\n\n  update(input) {\n    // Movement\n    const forward = new THREE.Vector3(0, 0, -1).applyQuaternion(this.target.quaternion);\n    const right = new THREE.Vector3(1, 0, 0).applyQuaternion(this.target.quaternion);\n\n    if (input.forward) this.target.position.add(forward.multiplyScalar(this.moveSpeed));\n    if (input.backward) this.target.position.add(forward.multiplyScalar(-this.moveSpeed));\n    if (input.left) this.target.position.add(right.multiplyScalar(-this.moveSpeed));\n    if (input.right) this.target.position.add(right.multiplyScalar(this.moveSpeed));\n\n    // Rotation\n    if (input.rotateLeft) this.target.rotation.y += this.rotationSpeed;\n    if (input.rotateRight) this.target.rotation.y -= this.rotationSpeed;\n\n    // Update camera position\n    const offset = new THREE.Vector3(0, this.height, this.distance);\n    offset.applyQuaternion(this.target.quaternion);\n    this.camera.position.copy(this.target.position).add(offset);\n    this.camera.lookAt(this.target.position);\n  }\n}\n```\n\n### Input Handling\n\n```javascript\nclass InputManager {\n  constructor() {\n    this.keys = {};\n    this.mouse = { x: 0, y: 0, buttons: {} };\n\n    window.addEventListener(''keydown'', (e) => this.keys[e.code] = true);\n    window.addEventListener(''keyup'', (e) => this.keys[e.code] = false);\n    window.addEventListener(''mousemove'', (e) => {\n      this.mouse.x = (e.clientX / window.innerWidth) * 2 - 1;\n      this.mouse.y = -(e.clientY / window.innerHeight) * 2 + 1;\n    });\n  }\n\n  getInput() {\n    return {\n      forward: this.keys[''KeyW''] || this.keys[''ArrowUp''],\n      backward: this.keys[''KeyS''] || this.keys[''ArrowDown''],\n      left: this.keys[''KeyA''] || this.keys[''ArrowLeft''],\n      right: this.keys[''KeyD''] || this.keys[''ArrowRight''],\n      jump: this.keys[''Space''],\n      action: this.keys[''KeyE''],\n      rotateLeft: this.keys[''KeyQ''],\n      rotateRight: this.keys[''KeyE'']\n    };\n  }\n}\n```\n\n### Collision Detection (Raycasting)\n\n```javascript\nfunction checkCollisions(player, obstacles) {\n  const raycaster = new THREE.Raycaster();\n  const directions = [\n    new THREE.Vector3(1, 0, 0),   // right\n    new THREE.Vector3(-1, 0, 0),  // left\n    new THREE.Vector3(0, 0, 1),   // forward\n    new THREE.Vector3(0, 0, -1),  // backward\n  ];\n\n  for (const direction of directions) {\n    raycaster.set(player.position, direction);\n    const intersects = raycaster.intersectObjects(obstacles);\n\n    if (intersects.length > 0 && intersects[0].distance < 1.0) {\n      return {\n        collision: true,\n        object: intersects[0].object,\n        distance: intersects[0].distance,\n        point: intersects[0].point\n      };\n    }\n  }\n\n  return { collision: false };\n}\n```\n\n### Loading 3D Models (GLTF)\n\n```javascript\nimport { GLTFLoader } from ''three/examples/jsm/loaders/GLTFLoader.js'';\n\nconst loader = new GLTFLoader();\n\nfunction loadCharacter(path) {\n  return new Promise((resolve, reject) => {\n    loader.load(\n      path,\n      (gltf) => {\n        const model = gltf.scene;\n        model.scale.set(1, 1, 1);\n        scene.add(model);\n\n        // Setup animations if available\n        const mixer = new THREE.AnimationMixer(model);\n        const animations = {};\n        gltf.animations.forEach(clip => {\n          animations[clip.name] = mixer.clipAction(clip);\n        });\n\n        resolve({ model, mixer, animations });\n      },\n      (progress) => {\n        console.log(`Loading: ${(progress.loaded / progress.total * 100).toFixed(2)}%`);\n      },\n      (error) => reject(error)\n    );\n  });\n}\n\n// Usage\nconst character = await loadCharacter(''/models/character.glb'');\ncharacter.animations.idle.play();\n```\n\n### Basic Physics (Gravity & Jumping)\n\n```javascript\nclass PhysicsBody {\n  constructor(mesh) {\n    this.mesh = mesh;\n    this.velocity = new THREE.Vector3();\n    this.onGround = false;\n    this.gravity = -9.8;\n    this.jumpPower = 5;\n  }\n\n  update(deltaTime) {\n    // Apply gravity\n    if (!this.onGround) {\n      this.velocity.y += this.gravity * deltaTime;\n    }\n\n    // Apply velocity\n    this.mesh.position.add(this.velocity.clone().multiplyScalar(deltaTime));\n\n    // Ground check\n    if (this.mesh.position.y <= 0) {\n      this.mesh.position.y = 0;\n      this.velocity.y = 0;\n      this.onGround = true;\n    }\n  }\n\n  jump() {\n    if (this.onGround) {\n      this.velocity.y = this.jumpPower;\n      this.onGround = false;\n    }\n  }\n}\n```\n\n### Interactive Objects (Picking)\n\n```javascript\nconst raycaster = new THREE.Raycaster();\nconst mouse = new THREE.Vector2();\n\nfunction onMouseClick(event) {\n  mouse.x = (event.clientX / window.innerWidth) * 2 - 1;\n  mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;\n\n  raycaster.setFromCamera(mouse, camera);\n  const intersects = raycaster.intersectObjects(interactableObjects);\n\n  if (intersects.length > 0) {\n    const object = intersects[0].object;\n    object.userData.onInteract?.();\n  }\n}\n\nwindow.addEventListener(''click'', onMouseClick);\n```\n\n### Health & Damage System\n\n```javascript\nclass Entity {\n  constructor(mesh, maxHealth) {\n    this.mesh = mesh;\n    this.maxHealth = maxHealth;\n    this.health = maxHealth;\n    this.isDead = false;\n  }\n\n  takeDamage(amount) {\n    if (this.isDead) return;\n\n    this.health = Math.max(0, this.health - amount);\n\n    if (this.health === 0) {\n      this.die();\n    }\n\n    return this.health;\n  }\n\n  heal(amount) {\n    this.health = Math.min(this.maxHealth, this.health + amount);\n    return this.health;\n  }\n\n  die() {\n    this.isDead = true;\n    this.mesh.visible = false;\n    // Trigger death animation, effects, etc.\n  }\n}\n```\n\n## Key Concepts\n\n### Scene Graph\n- Organize game objects hierarchically\n- Use groups for complex objects\n- Parent-child transformations\n\n### Game Loop\n- Use `requestAnimationFrame` for 60fps\n- Calculate delta time for frame-independent movement\n- Separate update logic from rendering\n\n### Camera Systems\n- **PerspectiveCamera**: First/third-person games\n- **OrthographicCamera**: 2D/isometric games\n- Implement camera follow and smooth transitions\n\n### Lighting\n- **AmbientLight**: Base illumination\n- **DirectionalLight**: Sun/moonlight with shadows\n- **PointLight**: Torches, explosions\n- **SpotLight**: Flashlights, stage lights\n\n### Performance Optimization\n- Use instancing for repeated objects\n- Implement frustum culling\n- Use LOD (Level of Detail) for distant objects\n- Minimize draw calls\n- Use texture atlases\n- Enable shadow map optimization\n\n### Asset Loading\n- Preload all assets before game start\n- Show loading progress bar\n- Use LoadingManager for coordination\n- Cache loaded assets\n\n## Common Game Patterns\n\n### State Machine (Game States)\n\n```javascript\nclass GameStateMachine {\n  constructor() {\n    this.states = {\n      menu: new MenuState(),\n      playing: new PlayingState(),\n      paused: new PausedState(),\n      gameOver: new GameOverState()\n    };\n    this.currentState = this.states.menu;\n  }\n\n  changeState(stateName) {\n    this.currentState.exit();\n    this.currentState = this.states[stateName];\n    this.currentState.enter();\n  }\n\n  update(deltaTime) {\n    this.currentState.update(deltaTime);\n  }\n}\n```\n\n### Object Pooling\n\n```javascript\nclass ObjectPool {\n  constructor(factory, initialSize = 10) {\n    this.factory = factory;\n    this.available = [];\n    this.inUse = [];\n\n    for (let i = 0; i < initialSize; i++) {\n      this.available.push(factory());\n    }\n  }\n\n  acquire() {\n    let obj = this.available.pop();\n    if (!obj) obj = this.factory();\n    this.inUse.push(obj);\n    return obj;\n  }\n\n  release(obj) {\n    const index = this.inUse.indexOf(obj);\n    if (index > -1) {\n      this.inUse.splice(index, 1);\n      this.available.push(obj);\n    }\n  }\n}\n\n// Usage\nconst bulletPool = new ObjectPool(() => createBullet(), 20);\nconst bullet = bulletPool.acquire();\n// ... use bullet\nbulletPool.release(bullet);\n```\n\n## Reference Files\n\nDetailed documentation organized by topic:\n\n- **getting_started.md** - Three.js fundamentals, setup, and basic concepts\n- **game_development.md** - Game loop, player controllers, game mechanics\n- **scene_graph.md** - Scene organization, hierarchy, transformations\n- **materials.md** - Material types, shaders, visual effects\n- **textures.md** - Texture loading, UV mapping, atlases\n- **lighting.md** - Light types, shadows, HDR\n- **cameras.md** - Camera types, controls, viewport management\n- **geometry.md** - Built-in geometries, custom geometry, buffers\n- **loading.md** - Asset loading (models, textures, audio)\n- **animation.md** - Animation system, skeletal animation, tweens\n- **interactivity.md** - Raycasting, picking, UI integration\n- **effects.md** - Post-processing, particles, fog\n\n## Resources\n\n### Official Documentation\n- Three.js Manual: https://threejs.org/manual/\n- Three.js API: https://threejs.org/docs/\n- Three.js Examples: https://threejs.org/examples/\n\n### Physics Integration\n- **Cannon.js**: Lightweight 3D physics\n- **Ammo.js**: Full Bullet physics engine port\n- **Rapier**: High-performance physics\n\n### Useful Libraries\n- **three-mesh-bvh**: Fast raycasting\n- **three-pathfinding**: Navigation meshes\n- **postprocessing**: Advanced effects\n\n## Working with This Skill\n\n### For Beginners\n1. Start with basic scene setup\n2. Learn the coordinate system\n3. Understand the game loop\n4. Practice with simple shapes before models\n\n### For Game Development\n1. Plan your game architecture\n2. Implement input handling first\n3. Build a simple player controller\n4. Add gameplay mechanics incrementally\n5. Optimize performance throughout\n\n### For Advanced Features\n1. Integrate physics engines\n2. Implement advanced shaders\n3. Add post-processing effects\n4. Build multiplayer networking\n\n## Notes\n\n- Three.js uses a right-handed coordinate system (X right, Y up, Z out)\n- Optimize early: profile regularly, minimize draw calls\n- Use development builds for debugging, production builds for release\n- Consider WebGL 2 features for modern browsers\n- Mobile performance requires careful optimization\n"},"lastSynced":"2026-02-18T03:12:13.865Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing immersive 3D game development capabilities with Three.js and WebGL","zh":"非常适合需要具有Three.js和WebGL的沉浸式3D游戏开发能力的前端代理","ja":"Three.jsとWebGLを使用したイミューシブな3Dゲーム開発機能を必要とするフロントエンドエージェントに最適","ko":"Three.js와 WebGL을 사용한 몰입형 3D 게임 개발 기능이 필요한 프론트엔드 에이전트에게 완벽한","es":"Perfecto para agentes frontend que necesitan capacidades de desarrollo de juegos 3D inmersivos con Three.js y WebGL","fr":"Parfait pour les agents frontend ayant besoin de capacités de développement de jeux 3D immersifs avec Three.js et WebGL","de":"Perfekt für Frontend-Agents, die immersive 3D-Spielentwicklungsfähigkeiten mit Three.js und WebGL benötigen","pt":"Perfeito para Agentes Frontend que necessitam de capacidades de desenvolvimento de jogos 3D imersivos com Three.js e WebGL","ru":"Идеально подходит для агентов Frontend, которым необходимы возможности разработки иммерсивных 3D-игр с использованием Three.js и WebGL","ar":"مثالي لعميل واجهة المستخدم الذين يحتاجون إلى قدرات تطوير ألعاب 3D الغامرة باستخدام Three.js و WebGL"},"recommendation":{"en":"Empowers agents to create interactive browser-based games with advanced 3D rendering, physics, and animations using Three.js, handling user input from keyboard, mouse, touch, and implementing game mechanics like player movement, collisions, and scoring","zh":"赋予代理创建具有高级3D渲染、物理和动画的交互式浏览器游戏的能力，使用Three.js，处理来自键盘、鼠标、触摸的用户输入，并实现游戏机制，如玩家移动、碰撞和计分","ja":"Three.jsを使用して、高度な3Dレンダリング、物理、動画を備えたインタラクティブなブラウザベースのゲームを作成するエージェントを可能にし、キーボード、マウス、タッチからのユーザー入力の処理と、プレイヤーの移動、衝突、スコアリングなどのゲームメカニズムの実装","ko":"Three.js를 사용하여 고급 3D 렌더링, 물리 및 애니메이션을 갖춘 상호작용 브라우저 게임을 생성할 수 있는 에이전트를 강화하여 키보드, 마우스, 터치로부터의 사용자 입력을 처리하고 플레이어 이동, 충돌 및 점수를 포함한 게임 메커니즘을 구현","es":"Habilita a los agentes a crear juegos de navegador interactivos con renderizado 3D avanzado, física y animacione