INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('nathanvale/vtm-cli/git-expert', 'community', 'nathanvale', 'vtm-cli', 'nathanvale/vtm-cli', 'git-expert', 0, 0, 45, '2026-02-18T01:08:43.406Z', '2026-02-18T03:19:14.701Z', NULL, '{"id":"nathanvale/vtm-cli/git-expert","name":"git-expert","description":{"zh":"Git 专家技能提供智能命令建议，帮助开发人员高效管理 Git 工作流。支持各种 Git 命令，包括状态、切换、创建、提交、拉取和推送等。","ja":"Git エキスパートスキルは、開発者が Git ワークフローを効率的に管理できるように、スマートなコマンドの提案を提供します。ステータス、切り替え、作成、コミット、プル、プッシュなどのさまざまな Git コマンドをサポートしています。","ko":"Git 전문가 기술은 개발자가 Git 워크플ロー 관리를 효율적으로 관리할 수 있도록智能 명령 제안을 제공합니다. 상태, 전환, 생성, 커밋, 풀, 푸시 등 다양한 Git 명령어를 지원합니다.","es":"El skill Git Expert ofrece gestión de tareas eficiente para desarrollo asistido con Claude Code, incluyendo sugerencias de comandos inteligentes","fr":"Le skill Git Expert propose une gestion de tâches efficace pour le développement assisté avec Claude Code, y compris des suggestions de commandes intelligentes","de":"Die Git-Expert-Fähigkeit bietet eine effiziente Aufgabenverwaltung für die KI-gestützte Entwicklung mit Claude Code, einschließlich intelligenter Befehlsvorschläge","pt":"O skill git-expert ajuda a gerenciar o fluxo de trabalho Git com sugestões de comandos inteligentes, melhorando a produtividade dos desenvolvedores.","ru":"Навык git-expert помогает управлять рабочим процессом Git с помощью умных предложений команд, повышая производительность разработчиков.","ar":"المهارة git-expert تساعد في إدارة تدفق عمل جيت باستخدام اقتراحات أوامر ذكية، وتحسين إنتاجية المطورين.","en":"Token-efficient task management for AI-assisted development with Claude Code"},"seo":{"title":{"zh":"Git 专家技能：AI 协助开发工作流管理","ja":"Git エキスパートスキル：AI アシスト開発ワークフローマネジメント","ko":"Git 전문가 기술: AI 보조 개발 워크플ロー 관리","es":"Experto en Git para Desarrollo Asistido","fr":"Expert Git pour Développement Assisté","de":"Git-Experte für KI-gestützte Entwicklung","pt":"Especialista em Git: Otimização de Fluxo de Trabalho","ru":"Эксперт Git: Управление рабочим процессом","ar":"خبير جيت: إدارة تدفق العمل","en":"git-expert"},"description":{"zh":"Git 专家技能提供智能命令建议，帮助开发人员高效管理 Git 工作流。支持各种 Git 命令，包括状态、切换、创建、提交、拉取和推送等。","ja":"Git エキスパートスキルは、開発者が Git ワークフローを効率的に管理できるように、スマートなコマンドの提案を提供します。ステータス、切り替え、作成、コミット、プル、プッシュなどのさまざまな Git コマンドをサポートしています。","ko":"Git 전문가 기술은 개발자가 Git 워크플ロー 관리를 효율적으로 관리할 수 있도록智能 명령 제안을 제공합니다. 상태, 전환, 생성, 커밋, 풀, 푸시 등 다양한 Git 명령어를 지원합니다.","es":"El skill Git Expert ofrece gestión de tareas eficiente para desarrollo asistido con Claude Code, incluyendo sugerencias de comandos inteligentes","fr":"Le skill Git Expert propose une gestion de tâches efficace pour le développement assisté avec Claude Code, y compris des suggestions de commandes intelligentes","de":"Die Git-Expert-Fähigkeit bietet eine effiziente Aufgabenverwaltung für die KI-gestützte Entwicklung mit Claude Code, einschließlich intelligenter Befehlsvors...","pt":"O skill git-expert ajuda a gerenciar o fluxo de trabalho Git com sugestões de comandos inteligentes, melhorando a produtividade dos desenvolvedores.","ru":"Навык git-expert помогает управлять рабочим процессом Git с помощью умных предложений команд, повышая производительность разработчиков.","ar":"المهارة git-expert تساعد في إدارة تدفق عمل جيت باستخدام اقتراحات أوامر ذكية، وتحسين إنتاجية المطورين.","en":"Token-efficient task management for AI-assisted development with Claude Code"},"definition":{"en":"Token-efficient task management for AI-assisted development with Claude Code"},"features":{"zh":["智能命令建议","支持多种 Git 命令","高效管理 Git 工作流","简化开发流程","减少错误"],"ja":["スマートなコマンドの提案","さまざまな Git コマンドのサポート","Git ワークフローの効率的な管理","開発プロセスの簡素化","エラーの減少"],"ko":["智能 명령 제안","다양한 Git 명령어 지원","Git 워크플ロー 효율적인 관리","개발 프로세스 간소화","오류 감소"],"es":["Sugerencias de comandos inteligentes","Gestión de ramas","Creación de commits","Historial de cambios","Funciones de extracción y envío de cambios"],"fr":["Suggestions de commandes intelligentes","Gestion de branches","Création de commits","Historique des modifications","Fonctions de téléchargement et d''envoi de modifications"],"de":["Intelligente Befehlsvorschläge","Zweigverwaltung","Erstellung von Commits","Änderungshistorie","Funktionen zum Abrufen und Senden von Änderungen"],"pt":["Sugestões de comandos inteligentes","Gerenciamento de branches","Criação de commits personalizados","Visualização do histórico de alterações","Integração com Claude Code"],"ru":["Умные предложения команд","Управление ветками","Создание индивидуальных коммитов","Просмотр истории изменений","Интеграция с Claude Code"],"ar":["اقتراحات أوامر ذكية","إدارة الفروع","إنشاء تعليمات مخصصة","عرض تاريخ التعديلات","دمج مع Claude Code"]},"keywords":{"zh":["Git 专家技能","AI 驱动开发","任务管理工具","Git 工作流管理","智能命令建议","开发效率提高"],"ja":["Git エキスパートスキル","AI ドライブ開発","タスク管理ツール","Git ワークフローマネジメント","スマートなコマンドの提案","開発効率の向上"],"ko":["Git 전문가 기술","AI 구동 개발","태스크 관리 도구","Git 워크플ロー 관리","智能 명령 제안","개발 효율성 향상"],"es":["desarrollo asistido","git expert","gestión de tareas","sugerencias de comandos","claude code","desarrollo de software","herramientas de desarrollo"],"fr":["développement assisté","expert git","gestion de tâches","suggestions de commandes","claude code","développement de logiciels","outils de développement"],"de":["KI-gestützte Entwicklung","git-experte","Aufgabenverwaltung","Befehlsvorschläge","claude code","Software-Entwicklung","Entwicklungstools"],"pt":["git","desenvolvimento de software","gerenciamento de fluxo de trabalho","produtividade","ferramentas de desenvolvimento","Claude Code","especialista em Git"],"ru":["git","разработка программного обеспечения","управление рабочим процессом","производительность","инструменты разработки","Claude Code","эксперт Git"],"ar":["جيت","تطوير البرمجيات","إدارة تدفق العمل","الإنتاجية","أدوات التطوير","Claude Code","خبير جيت"]}},"owner":"nathanvale","repo":"vtm-cli","repoPath":"nathanvale/vtm-cli","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.406Z","topics":[],"category":"community","skillMd":{"name":"git-expert","description":"|","bodyPreview":"# Git Expert Skill\n\n## What This Skill Does\n\nHelps you manage your git workflow with smart command suggestions.\n\n## Available Commands\n\n- `/git:status` - Get the current git status\n- `/git:switch` - Switch branches\n- `/git:create-branch` - Create a new branch\n- `/git:commit` - Make a commit with special instructions\n- `/git:pull` - Pull changes\n- `/git:push` - Push changes\n- `/git:log` - View history/what''s been done\n\n## When Claude Uses This\n\nWhen you mention things like:\n- \"what''s the git stat","body":"# Git Expert Skill\n\n## What This Skill Does\n\nHelps you manage your git workflow with smart command suggestions.\n\n## Available Commands\n\n- `/git:status` - Get the current git status\n- `/git:switch` - Switch branches\n- `/git:create-branch` - Create a new branch\n- `/git:commit` - Make a commit with special instructions\n- `/git:pull` - Pull changes\n- `/git:push` - Push changes\n- `/git:log` - View history/what''s been done\n\n## When Claude Uses This\n\nWhen you mention things like:\n- \"what''s the git status?\" → Suggests `/git:status`\n- \"I need to switch branches\" → Suggests `/git:switch`\n- \"create a new feature branch\" → Suggests `/git:create-branch`\n- \"let me commit my changes\" → Suggests `/git:commit`\n- \"pull the latest changes\" → Suggests `/git:pull`\n- \"push my commits\" → Suggests `/git:push`\n- \"show the commit history\" → Suggests `/git:log`\n\n## Best Practices\n\n1. **Before starting**: Run `/git:status` to see current state\n2. **Understand scope**: Verify which branch you''re on\n3. **Track progress**: Review commit history with `/git:log`\n4. **Keep updated**: Pull changes before pushing\n\n## Customization\n\nEdit the trigger phrases in the frontmatter above to match your vocabulary.\nKeep the skill description updated as you evolve the domain.\n\n## Integration\n\nWorks seamlessly with other Claude Code domains:\n- Can be invoked manually: `/git:operation`\n- Auto-triggered by Claude based on conversation\n- Works with other skills and commands\n\n## Common Workflows\n\n**Start a feature:**\n```\n/git:status                    # Check current state\n/git:create-branch feature/x   # Create new branch\n```\n\n**Commit and push:**\n```\n/git:status                    # Review changes\n/git:commit \"message\"          # Create commit\n/git:push origin branch-name   # Push to remote\n```\n\n**Update your branch:**\n```\n/git:pull origin main          # Get latest main\n# Resolve conflicts if needed\n/git:push origin branch-name   # Push your work\n```\n\n**Review history:**\n```\n/git:log --oneline 10          # Recent commits\n/git:log --graph --oneline     # Branch structure\n```\n"},"lastSynced":"2026-02-18T03:19:14.701Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing streamlined git workflow management with Claude Code","zh":"非常适合需要使用 Claude Code 进行流畅的 Git 工作流管理的开发代理","ja":"Claude Code を使用したスムーズな Git ワークフロー管理が必要な開発エージェントに最適","ko":"Claude Code를 사용하여 효율적인 Git 워크플로우 관리가 필요한 개발 에이전트에 적합","es":"Perfecto para agentes de desarrollo que necesitan una gestión de flujo de trabajo de git optimizada con Claude Code","fr":"Parfait pour les agents de développement ayant besoin d''une gestion de workflow Git simplifiée avec Claude Code","de":"Perfekt für Entwicklungssagenten, die eine optimierte Git-Workflow-Verwaltung mit Claude Code benötigen","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de gerenciamento de fluxo de trabalho do git simplificado com Claude Code","ru":"Идеально для агентов разработки, которым требуется упрощенное управление рабочим процессом git с помощью Claude Code","ar":"مثالي لعميل التطوير الذين يحتاجون إلى إدارة تدفق عمل جيت مبسط مع Claude Code"},"recommendation":{"en":"Empowers agents to manage git workflows efficiently using smart command suggestions, including branch switching, commit management, and history logging via commands like `/git:status`, `/git:switch`, and `/git:log`","zh":"赋予代理高效管理 Git 工作流的能力，包括使用智能命令建议进行分支切换、提交管理和历史记录日志，例如 `/git:status`、`/git:switch` 和 `/git:log` 命令","ja":"エージェントが `/git:status`、`/git:switch`、`/git:log` などのコマンドを使用して、ブランチの切り替え、コミットの管理、履歴のログ記録などのスマートなコマンドの提案を使用して Git ワークフローを効率的に管理できるようにする","ko":"에이전트가 `/git:status`, `/git:switch`, `/git:log`などの 명령을 사용하여 지능형 명령어 제안을 통해 효율적으로 Git 워크플로우를 관리할 수 있도록 하는데, 브랜치 전환, 커밋 관리, 기록 로그 등이 포함됨","es":"Permite a los agentes gestionar flujos de trabajo de git de manera eficiente mediante sugerencias de comandos inteligentes, incluyendo el cambio de ramas, la gestión de confirmaciones y la registrazione de historial a través de comandos como `/git:status`, `/git:switch` y `/git:log`","fr":"Permet aux agents de gérer les flux de travail Git de manière efficace à l''aide de suggestions de commandes intelligentes, notamment le commutation de branches, la gestion des validations et l''enregistrement de l''historique via des commandes comme `/git:status`, `/git:switch` et `/git:log`","de":"Ermöglicht es Agenten, Git-Workflows effizient zu verwalten, indem es intelligente Befehlsvorschläge verwendet, einschließlich Branch-Wechsel, Commit-Verwaltung und Historienprotokollierung über Befehle wie `/git:status`, `/git:switch` und `/git:log`","pt":"Habilita os agentes a gerenciar fluxos de trabalho do git de forma eficiente, usando sugestões de comandos inteligentes, incluindo alternância de branches, gerenciamento de commits e registro de histórico por meio de comandos como `/git:status`, `/git:switch` e `/git:log`","ru":"Наделяет агентов возможностью эффективно управлять рабочими процессами git, используя умные предложения команд, включая переключение веток, управление коммитами и ведение истории с помощью команд, таких как `/git:status`, `/git:switch` и `/git:log`","ar":"يمنح الوكلاء القدرة على إدارة تدفقات العمل جيت بفعالية باستخدام اقتراحات أوامر ذكية ، بما في ذلك تبديل الفروع وإدارة التعليقات وسجلات التاريخ من خلال أوامر مثل `/git:status` ، `/git:switch` و `/git:log`"},"useCases":{"en":["Automating git status checks","Switching branches efficiently with `/git:switch`","Generating commit messages with `/git:commit`","Pulling and pushing changes with `/git:pull` and `/git:push`"],"zh":["自动执行 Git 状态检查","使用 `/git:switch` 高效切换分支","使用 `/git:commit` 生成提交消息","使用 `/git:pull` 和 `/git:push` 拉取和推送更改"],"ja":["Git 状態のチェックを自動化する","`/git:switch` を使用してブランチを効率的に切り替える","`/git:commit` を使用してコミットメッセージを生成する","`/git:pull` と `/git:push` を使用して変更をプルおよびプッシュする"],"ko":["Git 상태检查 자동화","`/git:switch`를 사용하여 브랜치를 효율적으로 전환","`/git:commit`를 사용하여 커밋 메시지를 생성","`/git:pull` 및 `/git:push`를 사용하여 변경 사항을 가져오고 푸시"],"es":["Automatización de controles de estado de git","Cambio de ramas de manera eficiente con `/git:switch`","Generación de mensajes de confirmación con `/git:commit`","Extracción y envío de cambios con `/git:pull` y `/git:push`"],"fr":["Automatisation des vérifications d''état Git","Commutation de branches de manière efficace avec `/git:switch`","Génération de messages de validation avec `/git:commit`","Extraction et envoi de modifications avec `/git:pull` et `/git:push`"],"de":["Automatisierung von Git-Status-Checks","Effizientes Umstellen von Branches mit `/git:switch`","Generierung von Commit-Nachrichten mit `/git:commit`","Abrufen und Senden von Änderungen mit `/git:pull` und `/git:push`"],"pt":["Automatizar verificações de status do git","Alternar branches de forma eficiente com `/git:switch`","Gerar mensagens de commit com `/git:commit`","Fazer pull e push de alterações com `/git:pull` e `/git:push`"],"ru":["Автоматизировать проверки статуса git","Эффективно переключаться между ветками с помощью `/git:switch`","Генерировать сообщения о коммитах с помощью `/git:commit`","Выполнять pull и push изменений с помощью `/git:pull` и `/git:push`"],"ar":["تأتمتة فحص حالة جيت","تبديل الفروع بفعالية مع `/git:switch`","جعل رسائل التعليقات مع `/git:commit`","سحب و دفع التغييرات مع `/git:pull` و `/git:push`"]},"limitations":{"en":["Requires Claude Code integration","Git workflow management only"],"zh":["需要 Claude Code 集成","仅限 Git 工作流管理"],"ja":["Claude Code の統合が必要","Git ワークフローの管理のみ"],"ko":["Claude Code 통합이 필요","Git 워크플로우 관리만 가능"],"es":["Requiere integración con Claude Code","Gestión de flujo de trabajo de git solo"],"fr":["Nécessite une intégration avec Claude Code","Gestion du flux de travail Git uniquement"],"de":["Erfordert Integration mit Claude Code","Nur Git-Workflow-Verwaltung"],"pt":["Requer integração com Claude Code","Gerenciamento de fluxo de trabalho do git apenas"],"ru":["Требует интеграции с Claude Code","Управление рабочим процессом git только"],"ar":["يتطلب تكامل مع Claude Code","إدارة تدفق عمل جيت فقط"]},"version":3},"qualityScore":45}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('DonaldMurillo/momentum-cms/collection', 'community', 'DonaldMurillo', 'momentum-cms', 'DonaldMurillo/momentum-cms', 'collection', 0, 0, 50, '2026-02-18T01:08:43.406Z', '2026-02-18T03:19:33.316Z', NULL, '{"id":"DonaldMurillo/momentum-cms/collection","name":"collection","description":{"zh":"Momentum CMS集合功能允许开发者创建和管理项目数据。通过几个简单的步骤，开发者可以创建新的集合文件","ja":"Momentum CMSのコレクション機能を使用すると、開発者はプロジェクトデータを作成して管理できます。数ステップで新しいコレクションファイルを作成できます","ko":"Momentum CMS 컬렉션 기능을 사용하면 개발자가 프로젝트 데이터를 생성하고 관리할 수 있습니다. 몇 단계만 거치면 새로운 컬렉션 파일을 생성할 수 있습니다","es":"La colección es un componente fundamental en Momentum CMS. Aprende a crear una nueva colección con nuestro ejemplo de código","fr":"La collection est un composant fondamental dans Momentum CMS. Découvrez comment créer une nouvelle collection avec notre exemple de code","de":"Die Sammlung ist ein grundlegendes Komponente in Momentum CMS. Erfahren Sie, wie Sie eine neue Sammlung mit unserem Codebeispiel erstellen","pt":"O recurso de coleções do Momentum CMS permite criar estruturas de dados personalizadas. Aprenda a criar coleções com este guia.","ru":"Функция коллекций Momentum CMS позволяет создавать пользовательские структуры данных. Узнайте, как создавать коллекции с помощью этого руководства.","ar":"ميزة المجموعات في Momentum CMS تسمح بإنشاء هياكل بيانات مخصصة. تعلم كيفية إنشاء المجموعات باستخدام هذا الدليل.","en":""},"seo":{"title":{"zh":"Momentum CMS集合创建","ja":"Momentum CMSコレクション作成","ko":"Momentum CMS 컬렉션 생성","es":"Crear Colección Momentum CMS","fr":"Créer Collection Momentum CMS","de":"Erstellen Sie Momentum CMS-Sammlung","pt":"Crie Coleções no Momentum CMS","ru":"Создание коллекций в Momentum CMS","ar":"إنشاء مجموعات في Momentum CMS","en":"collection"},"description":{"zh":"Momentum CMS集合功能允许开发者创建和管理项目数据。通过几个简单的步骤，开发者可以创建新的集合文件","ja":"Momentum CMSのコレクション機能を使用すると、開発者はプロジェクトデータを作成して管理できます。数ステップで新しいコレクションファイルを作成できます","ko":"Momentum CMS 컬렉션 기능을 사용하면 개발자가 프로젝트 데이터를 생성하고 관리할 수 있습니다. 몇 단계만 거치면 새로운 컬렉션 파일을 생성할 수 있습니다","es":"La colección es un componente fundamental en Momentum CMS. Aprende a crear una nueva colección con nuestro ejemplo de código","fr":"La collection est un composant fondamental dans Momentum CMS. Découvrez comment créer une nouvelle collection avec notre exemple de code","de":"Die Sammlung ist ein grundlegendes Komponente in Momentum CMS. Erfahren Sie, wie Sie eine neue Sammlung mit unserem Codebeispiel erstellen","pt":"O recurso de coleções do Momentum CMS permite criar estruturas de dados personalizadas. Aprenda a criar coleções com este guia.","ru":"Функция коллекций Momentum CMS позволяет создавать пользовательские структуры данных. Узнайте, как создавать коллекции с помощью этого руководства.","ar":"ميزة المجموعات في Momentum CMS تسمح بإنشاء هياكل بيانات مخصصة. تعلم كيفية إنشاء المجموعات باستخدام هذا الدليل.","en":""},"definition":{"en":""},"features":{"zh":["创建新的集合文件","使用预定义的模板","支持多种数据类型","简化数据管理","提高开发效率"],"ja":["新しいコレクションファイルを作成","事前に定義されたテンプレートを使用","複数のデータタイプをサポート","データ管理を簡素化","開発効率を向上"],"ko":["새로운 컬렉션 파일 생성","사전 정의된 템플릿 사용","다양한 데이터 유형 지원","데이터 관리 단순화","개발 효율성 향상"],"es":["Crear archivos de colección personalizados","Definir esquemas de datos para las colecciones","Utilizar plantillas de código para agilizar el proceso","Compatibilidad con tipos de datos como texto, número y fecha","Posibilidad de crear relaciones entre colecciones"],"fr":["Créer des fichiers de collection personnalisés","Définir des schémas de données pour les collections","Utiliser des modèles de code pour accélérer le processus","Compatibilité avec des types de données tels que le texte, le nombre et la date","Possibilité de créer des relations entre les collections"],"de":["Erstellen Sie benutzerdefinierte Sammlungsdateien","Definieren Sie Datenschemata für die Sammlungen","Verwenden Sie Codevorlagen, um den Prozess zu beschleunigen","Kompatibilität mit Datentypen wie Text, Zahl und Datum","Möglichkeit, Beziehungen zwischen Sammlungen zu erstellen"],"pt":["Crie coleções personalizadas com campos personalizados","Defina estruturas de dados complexas com facilidade","Integre coleções com outros recursos do Momentum CMS","Use a API do Momentum CMS para manipular coleções","Crie coleções para gerenciar conteúdo de forma eficaz"],"ru":["Создавайте пользовательские коллекции с пользовательскими полями","Определите сложные структуры данных с легкостью","Интегрируйте коллекции с другими функциями Momentum CMS","Используйте API Momentum CMS для манипулирования коллекциями","Создавайте коллекции для эффективного управления контентом"],"ar":["انشئ مجموعات مخصصة مع حقول مخصصة","حدد هياكل بيانات معقدة بسهولة","ادمج المجموعات مع ميزات أخرى في Momentum CMS","استخدم واجهة برمجة التطبيقات Momentum CMS لتعديل المجموعات","انشئ مجموعات لإدارة المحتوى بفعالية"]},"keywords":{"zh":["Momentum CMS","集合","数据管理","开发效率","集合文件","模板"],"ja":["Momentum CMS","コレクション","データ管理","開発効率","コレクションファイル","テンプレート"],"ko":["Momentum CMS","컬렉션","데이터 관리","개발 효율성","컬렉션 파일","템플릿"],"es":["Momentum CMS","colección","desarrollo web","CMS","datos estructurados","esquema de datos","tipo de dato","relaciones entre colecciones"],"fr":["Momentum CMS","collection","développement web","CMS","données structurées","schéma de données","type de données","relations entre les collections"],"de":["Momentum CMS","Sammlung","Webentwicklung","CMS","strukturierte Daten","Datenschema","Datentyp","Beziehungen zwischen Sammlungen"],"pt":["Momentum CMS","coleções","estruturas de dados","campos personalizados","API","desenvolvimento web","gerenciamento de conteúdo"],"ru":["Momentum CMS","коллекции","структуры данных","пользовательские поля","API","веб-разработка","управление контентом"],"ar":["Momentum CMS","مجموعات","هياكل بيانات","حقول مخصصة","واجهة برمجة التطبيقات","تطوير الويب","إدارة المحتوى"]}},"owner":"DonaldMurillo","repo":"momentum-cms","repoPath":"DonaldMurillo/momentum-cms","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.406Z","topics":[],"category":"community","skillMd":{"name":"collection","description":"Generate a new Momentum CMS collection with fields, access control, and hooks","bodyPreview":"# Generate Momentum CMS Collection\n\nCreate a new collection file following project conventions.\n\n## Arguments\n\n- `$ARGUMENTS` - Collection name (e.g., \"posts\", \"products\", \"users\")\n\n## Steps\n\n1. Create the collection file at `collections/<name>.collection.ts`\n\n2. Use this template:\n\n```typescript\nimport {\n  defineCollection,\n  text,\n  richText,\n  number,\n  date,\n  checkbox,\n  select,\n  relationship,\n} from ''@momentumcms/core'';\n\nexport const <PascalName> = defineCollection({\n  slug: ''<kebab-name>","body":"# Generate Momentum CMS Collection\n\nCreate a new collection file following project conventions.\n\n## Arguments\n\n- `$ARGUMENTS` - Collection name (e.g., \"posts\", \"products\", \"users\")\n\n## Steps\n\n1. Create the collection file at `collections/<name>.collection.ts`\n\n2. Use this template:\n\n```typescript\nimport {\n  defineCollection,\n  text,\n  richText,\n  number,\n  date,\n  checkbox,\n  select,\n  relationship,\n} from ''@momentumcms/core'';\n\nexport const <PascalName> = defineCollection({\n  slug: ''<kebab-name>'',\n\n  admin: {\n    useAsTitle: ''title'', // or ''name'' - the field to display as title\n    defaultColumns: [''title'', ''createdAt''],\n    group: ''Content'', // Admin sidebar group\n  },\n\n  access: {\n    read: () => true,\n    create: ({ req }) => !!req.user,\n    update: ({ req }) => req.user?.role === ''admin'',\n    delete: ({ req }) => req.user?.role === ''admin'',\n  },\n\n  hooks: {\n    beforeChange: [],\n    afterChange: [],\n  },\n\n  fields: [\n    text(''title'', { required: true }),\n    // Add more fields as needed\n  ],\n});\n```\n\n3. Export from `collections/index.ts`:\n\n```typescript\nexport { <PascalName> } from ''./<name>.collection'';\n```\n\n4. Remind user to run schema generation:\n\n```bash\nnx run db-drizzle:generate-schema\nnpx drizzle-kit generate\n```\n\n## Field Types Available\n\n- `text(name, options)` - Short text\n- `richText(name, options)` - Rich text editor\n- `number(name, options)` - Numeric value\n- `date(name, options)` - Date/datetime\n- `checkbox(name, options)` - Boolean\n- `select(name, { options: [...] })` - Dropdown\n- `relationship(name, { collection: () => Ref })` - Reference to another collection\n- `array(name, { fields: [...] })` - Array of objects\n- `group(name, { fields: [...] })` - Nested object\n"},"lastSynced":"2026-02-18T03:19:33.316Z","agentAnalysis":{"suitability":{"en":"Perfect for TypeScript-based AI Agents needing structured data collection and management capabilities.","zh":"非常适合需要结构化数据收集和管理功能的基于TypeScript的AI代理。","ja":"TypeScriptベースのAIエージェントが構造化データの収集と管理機能を必要とする場合に最適です。","ko":"구조화된 데이터 수집 및 관리 기능이 필요한 TypeScript 기반 AI 에이전트에 적합합니다.","es":"Ideal para agentes de IA basados en TypeScript que necesitan capacidades de recopilación y gestión de datos estructurados.","fr":"Parfait pour les agents d''IA basés sur TypeScript nécessitant des capacités de collecte et de gestion de données structurées.","de":"Perfekt für auf TypeScript basierende KI-Agents, die Funktionen zur strukturierten Datensammlung und -verwaltung benötigen.","pt":"Perfeito para Agentes de IA baseados em TypeScript que necessitam de capacidades de coleta e gerenciamento de dados estruturados.","ru":"Идеально подходит для агентов ИИ на основе TypeScript, которым необходимы возможности структурированного сбора и управления данными.","ar":"مثالي لعمليات الوكيل الذكي التي تستند إلى TypeScript التي تحتاج إلى إمكانيات جمع البيانات والادارة المنظّمة."},"recommendation":{"en":"Empowers agents to define and generate collections using Momentum CMS, leveraging libraries like ''@momentumcms/core'' and creating files in the ''.collection.ts'' format, enabling efficient data organization and retrieval.","zh":"赋予代理定义和生成集合的能力，利用 Momentum CMS，并利用诸如 ''@momentumcms/core'' 之类的库，并以 ''.collection.ts'' 格式创建文件，从而实现高效的数据组织和检索。","ja":"エージェントにMomentum CMSを使用してコレクションを定義および生成する機能を付与し、''@momentumcms/core''などのライブラリを利用し、''.collection.ts''形式のファイルを作成して、効率的なデータの整理と取得を可能にします。","ko":"에이전트에 Momentum CMS를 사용하여 컬렉션을 정의 및 생성하는 기능을 부여하고, ''@momentumcms/core''와 같은 라이브러리를 활용하여 ''.collection.ts'' 형식의 파일을 생성함으로써 효율적인 데이터 조직 및 검색을 가능하게 합니다.","es":"Habilita a los agentes a definir y generar colecciones utilizando Momentum CMS, aprovechando bibliotecas como ''@momentumcms/core'' y creando archivos en el formato ''.collection.ts'', lo que permite una organización y recuperación de datos eficientes.","fr":"Permet aux agents de définir et de générer des collections en utilisant Momentum CMS, en exploitant des bibliothèques comme ''@momentumcms/core'' et en créant des fichiers au format ''.collection.ts'', ce qui permet une organisation et une récupération de données efficaces.","de":"Ermächtigt die Agents, Sammlungen mithilfe von Momentum CMS zu definieren und zu generieren, indem Bibliotheken wie ''@momentumcms/core'' genutzt und Dateien im ''.collection.ts''-Format erstellt werden, was eine effiziente Datenorganisation und -abruf ermöglicht.","pt":"Habilita os agentes a definir e gerar coleções usando o Momentum CMS, aproveitando bibliotecas como ''@momentumcms/core'' e criando arquivos no formato ''.collection.ts'', permitindo uma organização e recuperação de dados eficientes.","ru":"Наделяет агентов возможностью определять и генерировать коллекции с помощью Momentum CMS, используя библиотеки như ''@momentumcms/core'' и создавая файлы в формате ''.collection.ts'', что обеспечивает эффективную организацию и извлечение данных.","ar":"يسمح للوكلاء بتعريف وإنشاء مجموعات باستخدام Momentum CMS، واستخدام مكتبات مثل ''@momentumcms/core'' وإنشاء الملفات بنسيق ''.collection.ts''، مما يتيح منظمة بيانات وآليّة استرجاع فعالة."},"useCases":{"en":["Generating new collection files following project conventions","Defining custom collection structures with fields like text, richText, and relationship","Automating collection creation for various data types such as posts, products, and users"],"zh":["生成遵循项目约定的新集合文件","定义具有文本、richText和关系等字段的自定义集合结构","自动为各种数据类型（如帖子、产品和用户）创建集合"],"ja":["プロジェクトの約定に従った新しいコレクションファイルを生成する","テキスト、richText、関係などのフィールドを持つカスタムコレクション構造を定義する","投稿、製品、ユーザーなどの様々なデータ型に対してコレクションの自動作成を行う"],"ko":["프로젝트 규칙에 따라 새로운 컬렉션 파일을 생성한다","텍스트, 리치텍스트, 관계 등 필드를 가진 사용자 정의 컬렉션 구조를 정의한다","게시물, 제품, 사용자 등 다양한 데이터 유형에 대한 컬렉션 자동 생성"],"es":["Generar nuevos archivos de colección siguiendo las convenciones del proyecto","Definir estructuras de colección personalizadas con campos como texto, texto rico y relación","Automatizar la creación de colecciones para varios tipos de datos como publicaciones, productos y usuarios"],"fr":["Générer de nouveaux fichiers de collection suivant les conventions de projet","Définir des structures de collection personnalisées avec des champs tels que texte, texte riche et relation","Automatiser la création de collections pour différents types de données tels que des publications, des produits et des utilisateurs"],"de":["Erstellen neuer Sammlungsdateien unter Einhaltung der Projektkonventionen","Definieren benutzerdefinierter Sammlungsstrukturen mit Feldern wie Text, Rich-Text und Beziehung","Automatisieren der Sammlungserstellung für verschiedene Datentypen wie Beiträge, Produkte und Benutzer"],"pt":["Gerar novos arquivos de coleção seguindo as convenções do projeto","Definir estruturas de coleção personalizadas com campos como texto, richText e relacionamento","Automatizar a criação de coleções para vários tipos de dados, como posts, produtos e usuários"],"ru":["Генерировать новые файлы коллекций, следуя соглашениям проекта","Определять пользовательские структуры коллекций с полями, такими как текст, richText и связь","Автоматизировать создание коллекций для различных типов данных, таких как публикации, продукты и пользователи"],"ar":["توليد ملفات مجموعة جديدة تتبع اتفاقيات المشروع","تحديد هياكل مجموعة مخصصة مع حقول مثل النص، وrichText والارتباط","آليّة إنشاء مجموعات لمختلف أنواع البيانات، مثل المنشورات والمنتجات والمستخدمين"]},"limitations":{"en":["Requires Momentum CMS setup and configuration","Limited to TypeScript-based agents","Dependent on specific project conventions for collection file naming and structure"],"zh":["需要Momentum CMS的设置和配置","仅限于基于TypeScript的代理","依赖于特定的项目约定来命名和结构集合文件"],"ja":["Momentum CMSの設定と構成が必要","TypeScriptベースのエージェントのみに対応","コレクションファイルの命名と構造については、特定のプロジェクトの約定に依存する"],"ko":["Momentum CMS 설정 및 구성이 필요함","TypeScript 기반 에이전트만 해당됨","컬렉션 파일의 명명 및 구조에 대해서는 특정 프로젝트 규칙에 의존함"],"es":["Requiere configuración y setup de Momentum CMS","Limitado a agentes basados en TypeScript","Dependiente de convenciones de proyecto específicas para el nombre y la estructura de los archivos de colección"],"fr":["Nécessite une configuration et un setup de Momentum CMS","Limité aux agents basés sur TypeScript","Dépendant de conventions de projet spécifiques pour le nom et la structure des fichiers de collection"],"de":["Benötigt Einrichtung und Konfiguration von Momentum CMS","Eingeschränkt auf auf TypeScript basierende Agents","Abhängig von spezifischen Projektkonventionen für die Namensgebung und Struktur von Sammlungsdateien"],"pt":["Requer configuração e instalação do Momentum CMS","Limitado a agentes baseados em TypeScript","Dependente de convenções de projeto específicas para nomeação e estrutura de arquivos de coleção"],"ru":["Требует настройки и установки Momentum CMS","Ограничен агентами на основе TypeScript","Зависит от конкретных соглашений проекта для именования и структуры файлов коллекций"],"ar":["يتطلب إعداد وتثبيت Momentum CMS","محدود بالوكلاء التي تستند إلى TypeScript","يعتمد على اتفاقيات مشروع محددة لتسمية وهيكلة ملفات المجموعة"]},"version":3},"qualityScore":50}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('brianium/sfere/fx-explore', 'community', 'brianium', 'sfere', 'brianium/sfere', 'fx-explore', 0, 0, 60, '2026-02-18T01:08:43.406Z', '2026-02-18T03:19:37.122Z', NULL, '{"id":"brianium/sfere/fx-explore","name":"fx-explore","description":{"zh":"fx-explore 是 Twk 应用的连接管理库，提供 dispatch 函数和 schema 驱动的可发现性","ja":"fx-explore は Twk アプリの接続管理ライブラリであり、dispatch 関数と schema ドリブンの可発見性を提供します","ko":"fx-explore 는 Twk 애플리케이션의 연결 관리 라이브러리로서 dispatch 함수와 schema 驱动의可发现性을 제공합니다","es":"fx-explore es una biblioteca de gestión de conexiones para aplicaciones Twk que permite descubrir y entender efectos, acciones y marcadores. Se basa en la biblioteca Sandestin.","fr":"fx-explore est une bibliothèque de gestion des connexions pour les applications Twk qui permet de découvrir et de comprendre les effets, les actions et les marqueurs. Elle repose sur la bibliothèque Sandestin.","de":"fx-explore ist eine Bibliothek für die Verbindungsbereich für Twk-Anwendungen, die es ermöglicht, verfügbare Effekte, Aktionen und Platzhalter zu entdecken und zu verstehen. Sie basiert auf der Sandestin-Bibliothek.","pt":"O fx-explore é uma biblioteca de gerenciamento de conexão para aplicativos Twk, permitindo a descoberta de efeitos e ações disponíveis.","ru":"Fx-explore - это библиотека управления подключением для приложений Twk, обеспечивающая обнаружение доступных эффектов и действий.","ar":"fx-explore هي مكتبة لإدارة الاتصال لتطبيقات Twk، مما يسمح بالاكتشاف التأثيرات والactions المتاحة.","en":"Connection management for Twk apps"},"seo":{"title":{"zh":"fx-explore 连接管理 для Twk 应用","ja":"fx-explore 接続管理 for Twk アプリ","ko":"fx-explore 연결 관리 for Twk 애플리케이션","es":"fx-explore: Gestión de Conexiones para Aplicaciones Twk","fr":"fx-explore : Gestion des Connexions pour les Applications...","de":"fx-explore: Verbindungsbereich für Twk-Anwendungen","pt":"Gerenciamento de Conexão para Aplicativos Twk com fx-explore","ru":"Управление подключением для приложений Twk с помощью fx-e...","ar":"إدارة الاتصال لتطبيقات Twk باستخدام fx-explore","en":"fx-explore"},"description":{"zh":"fx-explore 是 Twk 应用的连接管理库，提供 dispatch 函数和 schema 驱动的可发现性","ja":"fx-explore は Twk アプリの接続管理ライブラリであり、dispatch 関数と schema ドリブンの可発見性を提供します","ko":"fx-explore 는 Twk 애플리케이션의 연결 관리 라이브러리로서 dispatch 함수와 schema 驱动의可发现性을 제공합니다","es":"fx-explore es una biblioteca de gestión de conexiones para aplicaciones Twk que permite descubrir y entender efectos, acciones y marcadores. Se basa en la bi...","fr":"fx-explore est une bibliothèque de gestion des connexions pour les applications Twk qui permet de découvrir et de comprendre les effets, les actions et les m...","de":"fx-explore ist eine Bibliothek für die Verbindungsbereich für Twk-Anwendungen, die es ermöglicht, verfügbare Effekte, Aktionen und Platzhalter zu entdecken u...","pt":"O fx-explore é uma biblioteca de gerenciamento de conexão para aplicativos Twk, permitindo a descoberta de efeitos e ações disponíveis.","ru":"Fx-explore - это библиотека управления подключением для приложений Twk, обеспечивающая обнаружение доступных эффектов и действий.","ar":"fx-explore هي مكتبة لإدارة الاتصال لتطبيقات Twk، مما يسمح بالاكتشاف التأثيرات والactions المتاحة.","en":"Connection management for Twk apps"},"definition":{"en":"Connection management for Twk apps"},"features":{"zh":["连接管理","dispatch 函数","schema 驱动的可发现性","Twk 应用支持","Clojure 整合"],"ja":["接続管理","dispatch 関数","schema ドリブンの可発見性","Twk アプリサポート","Clojure 統合"],"ko":["연결 관리","dispatch 함수","schema 驱动的可发现性","Twk 애플리케이션 지원","Clojure 통합"],"es":["Gestión de conexiones para aplicaciones Twk","Descubrimiento de efectos y acciones","Compatibilidad con la biblioteca Sandestin","Uso de la función dispatch para registries","Soporte para esquemas de descubrimiento"],"fr":["Gestion des connexions pour les applications Twk","Découverte d''effets et d''actions","Compatibilité avec la bibliothèque Sandestin","Utilisation de la fonction dispatch pour les registres","Prise en charge des schémas de découverte"],"de":["Verbindungsbereich für Twk-Anwendungen","Entdecken von Effekten und Aktionen","Kompatibilität mit der Sandestin-Bibliothek","Verwendung der Dispatch-Funktion für Registries","Unterstützung für Entdeckungsschemata"],"pt":["Gerenciamento de conexão para aplicativos Twk","Descoberta de efeitos e ações disponíveis","Criação de dispatch via (s/create-dispatch [registries...])","Suporte a esquemas de descoberta","Integração com bibliotecas de efeitos","Documentação completa no GitHub"],"ru":["Управление подключением для приложений Twk","Обнаружение доступных эффектов и действий","Создание диспетчера через (s/create-dispatch [registries...])","Поддержка схем обнаружения","Интеграция с библиотеками эффектов","Полная документация на GitHub"],"ar":["إدارة الاتصال لتطبيقات Twk","اكتشاف التأثيرات والactions المتاحة","إنشاء التوجيه عبر (s/create-dispatch [registries...])","دعم مخططات الاكتشاف","التكامل مع مكتبات التأثيرات","توثيق كامل على GitHub"]},"keywords":{"zh":["fx-explore","连接管理","Twk 应用","dispatch 函数","schema 驱动的可发现性","Clojure"],"ja":["fx-explore","接続管理","Twk アプリ","dispatch 関数","schema ドリブンの可発見性","Clojure"],"ko":["fx-explore","연결 관리","Twk 애플리케이션","dispatch 함수","schema 驱动的可发现性","Clojure"],"es":["fx-explore","gestión de conexiones","aplicaciones Twk","Sandestin","descubrimiento de efectos","acciones","registries","esquemas de descubrimiento"],"fr":["fx-explore","gestion des connexions","applications Twk","Sandestin","découverte d''effets","actions","registres","schémas de découverte"],"de":["fx-explore","Verbindungsbereich","Twk-Anwendungen","Sandestin","Entdecken von Effekten","Aktionen","Registries","Entdeckungsschemata"],"pt":["fx-explore","gerenciamento de conexão","aplicativos Twk","descoberta de efeitos","criação de dispatch","esquemas de descoberta","bibliotecas de efeitos","desenvolvimento de aplicativos"],"ru":["fx-explore","управление подключением","приложения Twk","обнаружение эффектов","создание диспетчера","схемы обнаружения","библиотеки эффектов","разработка приложений"],"ar":["fx-explore","إدارة الاتصال","تطبيقات Twk","اكتشاف التأثيرات","إنشاء التوجيه","مخططات الاكتشاف","مكتبات التأثيرات","تطوير التطبيقات"]}},"owner":"brianium","repo":"sfere","repoPath":"brianium/sfere","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.406Z","topics":[],"category":"community","skillMd":{"name":"fx-explore","description":"Discover available effects, actions, and placeholders in a Sandestin project. Use when asking what effects exist, searching for functionality, or needing example invocations. Keywords: effects, actions, dispatch, describe, grep, sample.","bodyPreview":"# Sandestin Effect Explorer\n\nDiscover and understand available effects, actions, and placeholders.\n\n**Important:** All discoverability functions operate on the **dispatch function**, not registries. You must first create a dispatch via `(s/create-dispatch [registries...])` before using these functions.\n\n## About Sandestin\n\nSandestin is a Clojure effect dispatch library with schema-driven discoverability. Effects are dispatched as vectors like `[:myapp/save-user {:name \"Alice\"}]`.\n\n**GitHub:** ht","body":"# Sandestin Effect Explorer\n\nDiscover and understand available effects, actions, and placeholders.\n\n**Important:** All discoverability functions operate on the **dispatch function**, not registries. You must first create a dispatch via `(s/create-dispatch [registries...])` before using these functions.\n\n## About Sandestin\n\nSandestin is a Clojure effect dispatch library with schema-driven discoverability. Effects are dispatched as vectors like `[:myapp/save-user {:name \"Alice\"}]`.\n\n**GitHub:** https://github.com/brianium/sandestin\n\n### Check if Installed\n\nLook for the dependency in `deps.edn`:\n\n```clojure\nio.github.brianium/sandestin {:git/tag \"v0.3.0\" :git/sha \"2be6acc\"}\n```\n\n### Install if Missing\n\nAdd to `deps.edn` under `:deps`:\n\n```clojure\n{:deps\n {io.github.brianium/sandestin {:git/tag \"v0.3.0\" :git/sha \"2be6acc\"}}}\n```\n\n## Workflow\n\n### 1. Find the Dispatch\n\nSearch for `create-dispatch` to locate the project''s dispatch namespace.\n\n### 2. Explore via REPL\n\n```clojure\n(require ''[ascolais.sandestin :as s])\n(require ''[<dispatch-ns> :refer [dispatch]])\n\n;; List everything\n(s/describe dispatch)\n\n;; Filter by type\n(s/describe dispatch :effects)\n(s/describe dispatch :actions)\n(s/describe dispatch :placeholders)\n\n;; Search by keyword\n(s/grep dispatch \"user\")\n(s/grep dispatch #\"save|create\")\n\n;; Get details on specific item\n(s/describe dispatch :some.ns/effect-name)\n\n;; Generate sample invocation\n(s/sample dispatch :some.ns/effect-name)\n\n;; See system requirements\n(s/system-schema dispatch)\n```\n\n## Output Format\n\nSummarize findings:\n\n```\n### Effects\n\n**:myapp.db/query** - Execute a SQL query\n  Requires: [:datasource]\n  Example: [:myapp.db/query \"SELECT * FROM users\" 42]\n\n### Actions\n\n**:myapp.user/create** - Create user and send welcome email\n  Expands to: db insert + email send\n```\n\n## Key Functions\n\n| Function | Purpose |\n|----------|---------|\n| `(s/describe dispatch)` | List all items |\n| `(s/describe dispatch :key)` | Details for specific item |\n| `(s/grep dispatch \"pattern\")` | Search by string/regex |\n| `(s/sample dispatch :key)` | Generate sample data |\n| `(s/system-schema dispatch)` | System requirements |\n"},"lastSynced":"2026-02-18T03:19:37.122Z","agentAnalysis":{"suitability":{"en":"Perfect for Clojure-based AI Agents needing advanced effect management and discoverability capabilities in Twk apps","zh":"适用于需要高级效果管理和发现能力的Clojure基于AI代理的Twk应用","ja":"ClojureベースのAIエージェントがTwkアプリで高度な効果管理と検出機能を必要とする場合に最適","ko":"클로저 기반 AI 에이전트가 Twk 애플리케이션에서 고급 효과 관리 및 발견 기능을 필요로 할 경우 적합","es":"Perfecto para agentes de inteligencia artificial basados en Clojure que necesitan capacidades de gestión de efectos y descubrimiento avanzadas en aplicaciones Twk","fr":"Parfait pour les agents d''intelligence artificielle basés sur Clojure nécessitant des capacités de gestion d''effets et de découverte avancées dans les applications Twk","de":"Perfekt für auf Clojure basierende KI-Agents, die erweiterte Effektmanagement- und Entdeckungsfunktionen in Twk-Apps benötigen","pt":"Perfeito para Agentes de IA baseados em Clojure que necessitam de gerenciamento de efeitos avançado e capacidades de descoberta em aplicativos Twk","ru":"Идеально подходит для агентов ИИ на основе Clojure, которым необходимы продвинутые возможности управления эффектами и обнаружения в приложениях Twk","ar":"مثالي للوكلاء الذكاء الاصطناعي القائم على Clojure التي تحتاج إلى إدارة متقدمة للأثار والاكتشاف في تطبيقات Twk"},"recommendation":{"en":"Empowers agents to dispatch effects as vectors, utilizing schema-driven discoverability with the Sandestin effect dispatch library, and operate on the dispatch function for seamless connection management","zh":"赋予代理以向量形式调度效果的能力，利用基于模式的发现功能和Sandestin效果调度库，并在调度函数上操作以实现无缝的连接管理","ja":"エージェントに効果をベクトルとしてディスパッチする機能を付与し、スキーマ駆動の発見可能性とSandestin効果ディスパッチライブラリを利用し、ディスパッチ関数で操作してシームレスな接続管理を実現する","ko":"에이전트에 효과를 벡터 형태로 디스패치하는 기능을 부여하며, 스키마 기반의 발견 가능성 및 Sandestin 효과 디스패치 라이브러리를 활용하고, 디스패치 함수에서 작동하여无缝な 연결 관리를 구현","es":"Habilita a los agentes a enviar efectos como vectores, utilizando la descubrimiento basada en esquemas con la biblioteca de envío de efectos Sandestin, y operar en la función de envío para una gestión de conexión sin problemas","fr":"Permet aux agents d''envoyer des effets sous forme de vecteurs, en utilisant la découverte basée sur les schémas avec la bibliothèque d''envoi d''effets Sandestin, et opère sur la fonction d''envoi pour une gestion de connexion transparente","de":"Ermöglicht es Agenten, Effekte als Vektoren zu senden, indem sie die schemabasierte Entdeckung mit der Sandestin-Effektsendebibliothek nutzen und auf der Sendefunktion für eine nahtlose Verbindungsbetriebsführung arbeiten","pt":"Habilita agentes a encaminhar efeitos como vetores, utilizando descoberta baseada em esquema com a biblioteca de envio de efeitos Sandestin, e operar na função de envio para gerenciamento de conexão sem interrupção","ru":"Наделяет агентов возможностью отправлять эффекты в виде векторов, используя обнаружение, основанное на схеме, с помощью библиотеки отправки эффектов Sandestin, и работать с функцией отправки для бесшовного управления соединениями","ar":"يمنح الوكلاء القدرة على إرسال الأثار كمتجهات، باستخدام اكتشاف يستند إلى مخطط مع مكتبة إرسال الأثار Sandestin، وتشغيل الدالة الإرسال لإدارة الاتصال دون انقطاع"},"useCases":{"en":["Discovering available effects and actions in Twk apps","Understanding placeholders for effective dispatch management","Creating dispatches via (s/create-dispatch [registries...]) for enhanced app connectivity"],"zh":["在Twk应用中发现可用的效果和操作","理解占位符以进行有效的调度管理","通过(s/create-dispatch [registries...])创建调度以增强应用程序的连接性"],"ja":["Twkアプリで使用可能な効果とアクションを発見する","効果的なディスパッチ管理のためのプレースホルダーの理解","アプリの接続性を高めるために(s/create-dispatch [registries...])を介してディスパッチを作成する"],"ko":["Twk 애플리케이션에서 사용 가능한 효과 및 동작을 발견","효과적인 디스패치 관리를 위한 플레이스 홀더 이해","애플리케이션의 연결성을 향상시키기 위해 (s/create-dispatch [registries...])를 통해 디스패치를 생성"],"es":["Descubrir efectos y acciones disponibles en aplicaciones Twk","Comprender placeholders para una gestión de envío efectiva","Crear envíos a través de (s/create-dispatch [registries...]) para una conectividad de aplicaciones mejorada"],"fr":["Découvrir les effets et les actions disponibles dans les applications Twk","Comprendre les placeholders pour une gestion d''envoi efficace","Créer des envois via (s/create-dispatch [registries...]) pour une connectivité d''applications améliorée"],"de":["Verfügbare Effekte und Aktionen in Twk-Apps entdecken","Platzhalter für eine effektive Sendungsverwaltung verstehen","Sendungen über (s/create-dispatch [registries...]) erstellen, um eine verbesserte App-Verbindung zu ermöglichen"],"pt":["Descobrir efeitos e ações disponíveis em aplicativos Twk","Entender espaçadores para gerenciamento de envio eficaz","Criar envios via (s/create-dispatch [registries...]) para conectividade de aplicativos aprimorada"],"ru":["Обнаружение доступных эффектов и действий в приложениях Twk","Понимание плейсхолдеров для эффективного управления отправкой","Создание отправок через (s/create-dispatch [registries...]) для улучшения подключения приложений"],"ar":["اكتشاف الأثار والافعال المتاحة في تطبيقات Twk","فهم المحلول للتحكم الفعال في الإرسال","إنشاء إرسالات عبر (s/create-dispatch [registries...]) لتحسين الاتصال بالتطبيقات"]},"limitations":{"en":["Requires creation of a dispatch via (s/create-dispatch [registries...]) before use","Operates on dispatch function, not registries","Specific to Clojure and Twk apps"],"zh":["需要通过(s/create-dispatch [registries...])创建调度后才能使用","在调度函数上操作，而不是注册表","特定于Clojure和Twk应用"],"ja":["使用する前に(s/create-dispatch [registries...])を介してディスパッチを作成する必要がある","ディスパッチ関数で操作するが、登録表では操作しない","ClojureおよびTwkアプリに特有"],"ko":["사용하기 전에 (s/create-dispatch [registries...])를 통해 디스패치를 생성해야 함","디스패치 함수에서 작동하지만 등록表에서는 작동하지 않음","클로저 및 Twk 애플리케이션에 특정"],"es":["Requiere la creación de un envío a través de (s/create-dispatch [registries...]) antes de su uso","Opera en la función de envío, no en los registros","Específico para Clojure y aplicaciones Twk"],"fr":["Nécessite la création d''un envoi via (s/create-dispatch [registries...]) avant son utilisation","Opère sur la fonction d''envoi, et non sur les registres","Spécifique à Clojure et aux applications Twk"],"de":["Erfordert die Erstellung eines Sendevorgangs über (s/create-dispatch [registries...]) vor der Verwendung","Funktioniert auf der Sendefunktion, nicht auf den Registern","Spezifisch für Clojure und Twk-Apps"],"pt":["Exige a criação de um envio via (s/create-dispatch [registries...]) antes do uso","Opera na função de envio, não nos registros","Específico para Clojure e aplicativos Twk"],"ru":["Требует создания отправки через (s/create-dispatch [registries...]) перед использованием","Работает с функцией отправки, а не с реестрами","Специфичен для Clojure и приложений Twk"],"ar":["يتطلب إنشاء إرسال عبر (s/create-dispatch [registries...]) قبل الاستخدام","يعمل على دالة الإرسال، وليس على السجلات","محدد لبرنامج Clojure وتطبيقات Twk"]},"version":3},"qualityScore":60}');
