INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('anadav/computer-structure-lecture-slides/extract-page', 'community', 'anadav', 'computer-structure-lecture-slides', 'anadav/computer-structure-lecture-slides', 'extract-page', 0, 0, 55, '2026-02-18T01:08:43.406Z', '2026-02-18T03:21:05.894Z', NULL, '{"id":"anadav/computer-structure-lecture-slides/extract-page","name":"extract-page","description":{"zh":"PDF","ja":"PDF","ko":"PDF ","es":"La herramienta extract-page extrae una página de un PDF como imagen PNG. Utiliza el script tools/extract_page.py para realizar la extracción.","fr":"L''outil extract-page extrait une page d''un PDF en tant qu''image PNG. Utilisez le script tools/extract_page.py pour effectuer l''extraction.","de":"Das Tool extract-page extrahiert eine Seite aus einem PDF als PNG-Bild. Verwenden Sie das Skript tools/extract_page.py, um die Extraktion durchzuführen.","pt":"A ferramenta extract-page permite extrair páginas de PDF como imagens PNG. Veja como usar e exemplos.","ru":"Инструмент extract-page позволяет извлекать страницы PDF в виде изображений PNG. См. как использовать и примеры.","ar":"أداة extract-page تسمح باستخراج صفحات من PDF كصور PNG. انظر كيفية استخدامها وأمثلة.","en":""},"seo":{"title":{"zh":"PDF","ja":"PDF","ko":"PDF ","es":"Herramienta de Extracción de Página de PDF","fr":"Outil d''Extraction de Page de PDF","de":"PDF-Seitenextraktions-Tool","pt":"Extraia Página de PDF com Ferramenta extract-page","ru":"Извлеките страницу PDF с помощью инструмента extract-page","ar":"استخراج صفحة من PDF باستخدام أداة extract-page","en":"extract-page"},"description":{"zh":"PDF","ja":"PDF","ko":"PDF ","es":"La herramienta extract-page extrae una página de un PDF como imagen PNG. Utiliza el script tools/extract_page.py para realizar la extracción.","fr":"L''outil extract-page extrait une page d''un PDF en tant qu''image PNG. Utilisez le script tools/extract_page.py pour effectuer l''extraction.","de":"Das Tool extract-page extrahiert eine Seite aus einem PDF als PNG-Bild. Verwenden Sie das Skript tools/extract_page.py, um die Extraktion durchzuführen.","pt":"A ferramenta extract-page permite extrair páginas de PDF como imagens PNG. Veja como usar e exemplos.","ru":"Инструмент extract-page позволяет извлекать страницы PDF в виде изображений PNG. См. как использовать и примеры.","ar":"أداة extract-page تسمح باستخراج صفحات من PDF كصور PNG. انظر كيفية استخدامها وأمثلة.","en":""},"definition":{"en":""},"features":{"zh":["PDF","PNG","","1-","Python"],"ja":["PDF","PNG","","1-","Python"],"ko":["PDF","PNG","","1-","Python"],"es":["Extracción de página de PDF como imagen PNG","Uso de línea de comandos","Opción de salida personalizada","Compatibilidad con números de página de 1 a n","Salida de imagen en formato PNG","Uso sencillo con el script tools/extract_page.py"],"fr":["Extraction de page de PDF en tant qu''image PNG","Utilisation en ligne de commande","Option de sortie personnalisée","Compatibilité avec les numéros de page de 1 à n","Sortie d''image au format PNG","Utilisation simple avec le script tools/extract_page.py"],"de":["Extraktion einer Seite aus einem PDF als PNG-Bild","Verwendung in der Kommandozeile","Option für benutzerdefinierten Ausgabepfad","Kompatibilität mit Seitenzahlen von 1 bis n","Ausgabebild im PNG-Format","Einfache Verwendung mit dem Skript tools/extract_page.py"],"pt":["Extraia páginas de PDF como imagens PNG","Uso básico com linha de comando","Opção de saída personalizada","Números de página indexados a partir de 1"],"ru":["Извлеките страницы PDF в виде изображений PNG","Базовое использование через командную строку","Возможность настраивать выходной путь","Номера страниц индексируются, начиная с 1"],"ar":["استخراج صفحات من PDF كصور PNG","استخدام أساسي مع سطر الأوامر","خيار مخرج مخصص","أرقام الصفحات المُفهرسة تبدأ من 1"]},"keywords":{"zh":["PDF","extract-page","Python","PNG","PDF","1-"],"ja":["PDF","extract-page","Python","PNG","PDF","1-"],"ko":["PDF","extract-page","Python","PNG","PDF","1-"],"es":["herramienta de extracción de página de PDF","extract-page","extracción de página de PDF","imagen PNG","línea de comandos","salida personalizada","números de página","formato PNG"],"fr":["outil d''extraction de page de PDF","extract-page","extraction de page de PDF","image PNG","ligne de commande","sortie personnalisée","numéros de page","format PNG"],"de":["PDF-Seitenextraktions-Tool","extract-page","Extraktion einer Seite aus einem PDF","PNG-Bild","Kommandozeile","benutzerdefinierter Ausgabepfad","Seitenzahlen","PNG-Format"],"pt":["ferramenta extract-page","extrair página de PDF","PDF para PNG","linha de comando","saída personalizada","números de página indexados"],"ru":["инструмент extract-page","извлечь страницу PDF","PDF в PNG","командная строка","настраиваемый выходной путь","индексированные номера страниц"],"ar":["أداة extract-page","استخراج صفحة من PDF","PDF إلى PNG","سطر الأوامر","مخرج مخصص","أرقام صفحات مُفهرسة"]}},"owner":"anadav","repo":"computer-structure-lecture-slides","repoPath":"anadav/computer-structure-lecture-slides","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.406Z","topics":[],"category":"community","skillMd":{"name":"extract-page","description":"Extract a single page from a PDF as a PNG image for quick preview.","bodyPreview":"# Extract PDF Page Tool\n\nUse `tools/extract_page.py` to extract a single page from a PDF as a PNG image.\n\n## Usage\n\n**Basic usage:**\n```bash\npython tools/extract_page.py $ARGUMENTS[0] $ARGUMENTS[1]\n```\n\n**With custom output path:**\n```bash\npython tools/extract_page.py <file>.pdf <page> -o output.png\n```\n\n## Examples\n\n```bash\n# Extract page 5 from build/lecture.pdf\npython tools/extract_page.py build/lecture.pdf 5\n\n# Output will be: build/lecture.page5.png\n```\n\n## Notes\n\n- Page numbers are 1-index","body":"# Extract PDF Page Tool\n\nUse `tools/extract_page.py` to extract a single page from a PDF as a PNG image.\n\n## Usage\n\n**Basic usage:**\n```bash\npython tools/extract_page.py $ARGUMENTS[0] $ARGUMENTS[1]\n```\n\n**With custom output path:**\n```bash\npython tools/extract_page.py <file>.pdf <page> -o output.png\n```\n\n## Examples\n\n```bash\n# Extract page 5 from build/lecture.pdf\npython tools/extract_page.py build/lecture.pdf 5\n\n# Output will be: build/lecture.page5.png\n```\n\n## Notes\n\n- Page numbers are 1-indexed\n- Default output: `<file>.page<N>.png`\n- Uses pdftoppm (poppler), sips (macOS), or ImageMagick convert\n"},"lastSynced":"2026-02-18T03:21:05.894Z","agentAnalysis":{"suitability":{"en":"Perfect for Document Analysis Agents needing precise PDF page extraction capabilities.","zh":"非常适合需要精确PDF页提取能力的文档分析代理。","ja":"ドキュメント分析エージェントが正確なPDFページ抽出機能を必要とする場合に最適です。","ko":"정확한 PDF 페이지 추출 기능이 필요한 문서 분석 에이전트에 적합합니다.","es":"Perfecto para Agentes de Análisis de Documentos que necesitan capacidades de extracción de páginas de PDF precisas.","fr":"Parfait pour les Agents d''Analyse de Documents nécessitant des capacités d''extraction de pages PDF précises.","de":"Perfekt für Dokumentenanalyse-Agenten, die präzise PDF-Seitenausextraktionsfunktionen benötigen.","pt":"Perfeito para Agentes de Análise de Documentos que necessitam de capacidades de extração de páginas de PDF precisas.","ru":"Идеально для агентов анализа документов, которым требуются точные возможности извлечения страниц PDF.","ar":"مثالي لعميل تحليل المستندات الذين يحتاجون إلى القدرات الدقيقة لاستخراج صفحات PDF."},"recommendation":{"en":"Empowers agents to extract specific pages from PDF files as PNG images using Python, enabling advanced data visualization and processing with tools like extract_page.py, and supporting custom output paths.","zh":"使代理能够使用Python从PDF文件中提取特定页面作为PNG图像，实现使用extract_page.py等工具进行高级数据可视化和处理，并支持自定义输出路径。","ja":"エージェントがPythonを使用してPDFファイルから特定のページをPNG画像として抽出できるようにし、extract_page.pyなどのツールを使用した高度なデータ視覚化と処理を可能にし、カスタム出力パスもサポートします。","ko":"에이전트가 Python을 사용하여 PDF 파일에서 특정 페이지를 PNG 이미지로 추출할 수 있도록 하여 extract_page.py와 같은 도구를 사용한 고급 데이터 시각화 및 처리를 가능하게 하며 사용자 지정 출력 경로도 지원합니다.","es":"Habilita a los agentes a extraer páginas específicas de archivos PDF como imágenes PNG utilizando Python, lo que permite una visualización y procesamiento de datos avanzados con herramientas como extract_page.py, y admite rutas de salida personalizadas.","fr":"Permet aux agents d''extraire des pages spécifiques de fichiers PDF sous forme d''images PNG à l''aide de Python, permettant ainsi une visualisation et un traitement de données avancés avec des outils comme extract_page.py, et prend en charge des chemins de sortie personnalisés.","de":"Ermöglicht es Agenten, bestimmte Seiten von PDF-Dateien als PNG-Bilder mit Python zu extrahieren, wodurch eine erweiterte Datenvisualisierung und -verarbeitung mit Tools wie extract_page.py ermöglicht wird und benutzerdefinierte Ausgabepfade unterstützt.","pt":"Habilita os agentes a extrair páginas específicas de arquivos PDF como imagens PNG usando Python, permitindo visualização de dados avançada e processamento com ferramentas como extract_page.py, e suportando caminhos de saída personalizados.","ru":"Наделяет агентов возможностью извлекать конкретные страницы из файлов PDF в виде изображений PNG с использованием Python, обеспечивая расширенную визуализацию данных и обработку с помощью инструментов, таких как extract_page.py, и поддержку пользовательских путей вывода.","ar":"تمكين العميل من استخراج صفحات محددة من ملفات PDF كصور PNG باستخدام Python ، وتمكينه من تحليل البيانات المتقدم والمعالجة باستخدام أدوات مثل extract_page.py ، ودعم مسارات الإخراج المخصصة."},"useCases":{"en":["Extracting relevant pages from large PDF documents","Converting PDF pages to images for further analysis","Automating document processing workflows with precise page control"],"zh":["从大型PDF文档中提取相关页面","将PDF页面转换为图像以进行进一步分析","使用精确的页面控制自动化文档处理工作流"],"ja":["大きなPDF文書から関連するページを抽出する","PDFページを画像に変換してさらに分析する","正確なページ制御を使用してドキュメント処理ワークフローを自動化する"],"ko":["대형 PDF 문서에서 관련 페이지 추출","PDF 페이지를 이미지로 변환하여 추가 분석","정확한 페이지 제어를 사용한 문서 처리 워크플로 자동화"],"es":["Extraer páginas relevantes de grandes documentos PDF","Convertir páginas de PDF a imágenes para un análisis posterior","Automatizar flujos de trabajo de procesamiento de documentos con un control de página preciso"],"fr":["Extraire des pages pertinentes de grands documents PDF","Convertir des pages PDF en images pour une analyse ultérieure","Automatiser les flux de travail de traitement de documents avec un contrôle de page précis"],"de":["Extrahieren von relevanten Seiten aus großen PDF-Dokumenten","Umwandeln von PDF-Seiten in Bilder für eine weitere Analyse","Automatisieren von Dokumentenverarbeitungsworkflows mit präziser Seiteneinstellung"],"pt":["Extrair páginas relevantes de documentos PDF grandes","Converter páginas PDF em imagens para análise posterior","Automatizar fluxos de trabalho de processamento de documentos com controle de página preciso"],"ru":["Извлечение релевантных страниц из больших документов PDF","Преобразование страниц PDF в изображения для дальнейшего анализа","Автоматизация рабочих процессов обработки документов с точным контролем страниц"],"ar":["استخراج الصفحات ذات الصلة من المستندات الكبيرة PDF","تحويل صفحات PDF إلى صور لتحليل لاحق","آليته عمليات معالجة المستندات مع التحكم الدقيق في الصفحات"]},"limitations":{"en":["Requires Python environment","Page numbers are 1-indexed","Output format limited to PNG images"],"zh":["需要Python环境","页码是1索引的","输出格式仅限PNG图像"],"ja":["Python環境が必要","ページ番号は1インデックス","出力形式はPNG画像のみ"],"ko":["Python 환경이 필요함","페이지 번호는 1인덱스","출력 형식은 PNG 이미지만"],"es":["Requiere un entorno de Python","Los números de página están indexados en 1","El formato de salida está limitado a imágenes PNG"],"fr":["Nécessite un environnement Python","Les numéros de page sont indexés à 1","Le format de sortie est limité aux images PNG"],"de":["Benötigt eine Python-Umgebung","Seitenzahlen sind 1-indexiert","Das Ausgabeformat ist auf PNG-Bilder beschränkt"],"pt":["Requer ambiente Python","Os números de página são indexados em 1","Formato de saída limitado a imagens PNG"],"ru":["Требуется среда Python","Номера страниц индексируются с 1","Формат вывода ограничен изображениями PNG"],"ar":["يتطلب بيئة Python","أرقام الصفحات مؤشرات 1","تنسيق الإخراج مقيد بصور PNG"]},"version":3},"qualityScore":55}');
