INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ddoman90/claude-code-intro/clean-typescript', 'community', 'ddoman90', 'claude-code-intro', 'ddoman90/claude-code-intro', 'clean-typescript', 0, 0, 20, '2026-02-18T01:08:43.407Z', '2026-02-18T03:23:45.791Z', NULL, '{"id":"ddoman90/claude-code-intro/clean-typescript","name":"clean-typescript","description":{"zh":"Clean TypeScript是一种编码风格指南，旨在提高代码的正确性和可读性","ja":"Clean TypeScriptは、コードの正確性と可読性を向上させるためのスタイルガイドです","ko":"클린 TypeScript는 코드의 정확성과 가독성을 향상시키는ための 스타일 가이드입니다","es":"La guía de estilos de TypeScript limpio te ayuda a escribir código más claro y correcto, priorizando la legibilidad y la composabilidad","fr":"Le guide de style TypeScript propre vous aide à écrire du code plus clair et plus correct, en donnant la priorité à la lisibilité et à la composition","de":"Die Clean TypeScript-Stilguide hilft Ihnen, klareren und korrekteren Code zu schreiben, indem Sie Lesbarkeit und Komposition priorisieren","pt":"O guia de estilo TypeScript limpo ajuda a melhorar a legibilidade e reduzir bugs no código. Aprenda a usar tipos e funções de forma eficaz.","ru":"Чистый стиль TypeScript помогает улучшить читаемость и уменьшить ошибки в коде. Узнайте, как эффективно использовать типы и функции.","ar":"دليل نمط TypeScript النظيف يساعد على تحسين độ القراءة وتقليل العيوب في الكود. تعلم كيفية استخدام الأنواع والدوال بفعالية.","en":""},"seo":{"title":{"zh":"Clean TypeScript编码风格指南","ja":"Clean TypeScriptスタイルガイド","ko":"클린 TypeScript 스타일 가이드","es":"Guía de Estilos de TypeScript Limpio","fr":"Guide de Style TypeScript Propre","de":"Clean TypeScript-Stilguide","pt":"Guia de Estilo TypeScript Limpo","ru":"Чистый Стиль TypeScript","ar":"دليل نمط TypeScript النظيف","en":"clean-typescript"},"description":{"zh":"Clean TypeScript是一种编码风格指南，旨在提高代码的正确性和可读性","ja":"Clean TypeScriptは、コードの正確性と可読性を向上させるためのスタイルガイドです","ko":"클린 TypeScript는 코드의 정확성과 가독성을 향상시키는ための 스타일 가이드입니다","es":"La guía de estilos de TypeScript limpio te ayuda a escribir código más claro y correcto, priorizando la legibilidad y la composabilidad","fr":"Le guide de style TypeScript propre vous aide à écrire du code plus clair et plus correct, en donnant la priorité à la lisibilité et à la composition","de":"Die Clean TypeScript-Stilguide hilft Ihnen, klareren und korrekteren Code zu schreiben, indem Sie Lesbarkeit und Komposition priorisieren","pt":"O guia de estilo TypeScript limpo ajuda a melhorar a legibilidade e reduzir bugs no código. Aprenda a usar tipos e funções de forma eficaz.","ru":"Чистый стиль TypeScript помогает улучшить читаемость и уменьшить ошибки в коде. Узнайте, как эффективно использовать типы и функции.","ar":"دليل نمط TypeScript النظيف يساعد على تحسين độ القراءة وتقليل العيوب في الكود. تعلم كيفية استخدام الأنواع والدوال بفعالية.","en":""},"definition":{"en":""},"features":{"zh":["优先使用type别名","使用interface定义公共的、可扩展的对象形状","保持类型小巧和可组合","显式返回类型","谨慎使用函数重载"],"ja":["typeエイリアスを優先して使用する","interfaceを使用して公開された、拡張可能なオブジェクトの形状を定義する","型を小さくかつ合成可能にする","明示的な戻り値の型","関数のオーバーロードを慎重に使用する"],"ko":["타입 별名을 우선하여 사용","인터페이스를 사용하여 공개된, 확장 가능한 객체의 형태를 정의","타입을 작고 구성 가능하게 유지","명시적인 반환 타입","함수 오버로드를 신중하게 사용"],"es":["Declaraciones de tipo preferidas","Diseño de funciones explícitas","Gestión de nulidad","Priorización de la legibilidad","Composabilidad de tipos","Uso de interfaces para objetos públicos"],"fr":["Déclarations de type préférées","Conception de fonctions explicites","Gestion de la nulité","Priorisation de la lisibilité","Composabilité de types","Utilisation d''interfaces pour les objets publics"],"de":["Bevorzugte Typdeklarationen","Explizite Funktionsdesign","Nullitätsbehandlung","Priorisierung von Lesbarkeit","Komposition von Typen","Verwendung von Schnittstellen für öffentliche Objekte"],"pt":["Uso de aliases de tipo para situações comuns","Uso de interfaces para formas de objeto públicas e extensíveis","Manuseio de nulidade para reduzir erros","Funções com tipos de retorno explícitos","Uso de sobrecargas de funções de forma parcimoniosa"],"ru":["Использование псевдонимов типов для обычных ситуаций","Использование интерфейсов для публичных и расширяемых форм объектов","Обработка нуллирования для уменьшения ошибок","Функции с явными типами возвращаемых значений","Использование перегрузок функций в меру"],"ar":["استخدام أسماء مستعارة للأنواع في الحالات الشائعة","استخدام الواجهات لاشكال الكائنات العامة والقابلة للتوسيع","معالجة القيمة Null لتحسين الأداء","الدوال ذات أنواع الإرجاع الصريحة","استخدام التحميل الزائد للدوال بحكمة"]},"keywords":{"zh":["TypeScript","Clean TypeScript","编码风格指南","代码正确性","代码可读性","类型定义","函数设计"],"ja":["TypeScript","Clean TypeScript","スタイルガイド","コードの正確性","コードの可読性","型定義","関数設計"],"ko":["TypeScript","클린 TypeScript","스타일 가이드","코드의 정확성","코드의 가독성","타입 정의","함수 설계"],"es":["TypeScript","guía de estilos","código limpio","legibilidad","composabilidad","declaraciones de tipo","diseño de funciones","nulidad","mantenimiento de código"],"fr":["TypeScript","guide de style","code propre","lisibilité","composabilité","déclarations de type","conception de fonctions","nulité","maintenance de code"],"de":["TypeScript","Stilguide","sauberer Code","Lesbarkeit","Komposition","Typdeklarationen","Funktionsdesign","Nullität","Code-Wartung"],"pt":["TypeScript limpo","Guia de estilo TypeScript","Desenvolvimento de software","Programação eficaz","Legibilidade de código","Redução de bugs"],"ru":["Чистый TypeScript","Стиль TypeScript","Разработка программного обеспечения","Эффективное программирование","Читаемость кода","Уменьшение ошибок"],"ar":["TypeScript النظيف","دليل نمط TypeScript","تطوير البرمجيات","البرمجة الفعالة","قراءة الكود","تقليل العيوب"]}},"owner":"ddoman90","repo":"claude-code-intro","repoPath":"ddoman90/claude-code-intro","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.407Z","topics":[],"category":"community","skillMd":{"name":"clean-typescript","description":"Write clean, practical TypeScript focused on correctness over ceremony","bodyPreview":"# Clean TypeScript Style Guide\n\nUse TypeScript as a correctness and clarity tool, not as ceremony. Prioritize readable types that genuinely reduce bugs.\n\n## Type Declaration\n\n- **PREFER** `type` aliases for most situations\n- **USE** `interface` for public, extensible object shapes\n- Keep types small and composable\n\n## Function Design\n\n- **PREFER** explicit return types for public functions\n- Use function overloads sparingly, only when they meaningfully enhance the API\n\n## Nullability\n\n- Handle `","body":"# Clean TypeScript Style Guide\n\nUse TypeScript as a correctness and clarity tool, not as ceremony. Prioritize readable types that genuinely reduce bugs.\n\n## Type Declaration\n\n- **PREFER** `type` aliases for most situations\n- **USE** `interface` for public, extensible object shapes\n- Keep types small and composable\n\n## Function Design\n\n- **PREFER** explicit return types for public functions\n- Use function overloads sparingly, only when they meaningfully enhance the API\n\n## Nullability\n\n- Handle `null` and `undefined` explicitly through control flow and guards\n- **AVOID** non-null assertions (`!`) as regular practice\n\n## Avoid Anti-patterns\n\n- **AVOID** `enum` - use union types or `as const` objects instead\n- **AVOID** `any` - use `unknown` as the safer alternative\n\n## Error Handling\n\n- Type errors explicitly\n- Consider result objects or typed errors over broad exception throwing\n\n## Philosophy\n\nIf a type is hard to understand, it''s probably wrong. Prioritize maintainability and clear intent over theoretical type system completeness.\n"},"lastSynced":"2026-02-18T03:23:45.791Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Generation Agents requiring maintainable and readable TypeScript codebases.","zh":"适用于需要可维护和可读的TypeScript代码库的代码生成代理。","ja":"メンテナブルで読みやすいTypeScriptコードベースを必要とするコード生成エージェントに最適です。","ko":"유지 보수 있고 읽기 쉽게 TypeScript 코드베이스가 필요한 코드 생성 에이전트에 적합합니다.","es":"Ideal para agentes de generación de código que requieren bases de código de TypeScript mantenibles y legibles.","fr":"Idéal pour les agents de génération de code nécessitant des bases de code TypeScript maintenables et lisibles.","de":"Ideal für Code-Generierungsagenten, die wartbare und lesbare TypeScript-Codebasen erfordern.","pt":"Ideal para Agentes de Geração de Código que exigem bases de código TypeScript mantidas e legíveis.","ru":"Идеально для агентов генерации кода, требующих поддерживаемых и читаемых баз кода TypeScript.","ar":"مثالية لعميل توليد الشفرة الذي يتطلب قاعدة شفرة TypeScript قابلة للصيانة وقابلة للقراءة."},"recommendation":{"en":"Empowers agents to write clean, composable, and scalable TypeScript code using type aliases, interfaces, and explicit return types, reducing bugs and enhancing code clarity with features like function overloads and nullability handling.","zh":"赋予代理使用类型别名、接口和显式返回类型编写干净、可组合和可扩展的TypeScript代码的能力，通过诸如函数重载和可空性处理等功能减少错误并提高代码清晰度。","ja":"タイプエイリアス、インターフェイス、明示的な戻り値の型を使用してクリーンで構成可能でスケーラブルなTypeScriptコードを書くことができるエージェントをEmpowerし、関数のオーバーロードやnull safetyハンドリングなどの機能でバグを減らし、コードの明瞭性を高めます。","ko":"타입 에일리어스, 인터페이스 및 명시적 반환 유형을 사용하여 깨끗하고 구성 가능하며 확장 가능한 TypeScript 코드를 작성할 수 있는 에이전트를 강화하여 함수 오버로드 및 널 가능성 처리와 같은 기능으로 버그를 줄이고 코드의 명확성을 향상합니다.","es":"Habilita a los agentes a escribir código TypeScript limpio, componible y escalable utilizando alias de tipos, interfaces y tipos de retorno explícitos, reduciendo errores y mejorando la claridad del código con características como sobrecargas de funciones y manejo de nulabilidad.","fr":"Permet aux agents d''écrire du code TypeScript propre, composable et évolutif en utilisant des alias de types, des interfaces et des types de retour explicites, en réduisant les bogues et en améliorant la clarté du code avec des fonctionnalités comme les surcharges de fonctions et la gestion de la nulabilité.","de":"Ermöglich es den Agenten, sauberen, komponierbaren und skalierbaren TypeScript-Code mit Typaliasen, Schnittstellen und expliziten Rückgabetypen zu schreiben, indem es Fehler reduziert und die Codeklarheit mit Funktionen wie Funktionsüberladungen und Nullheitsbehandlung verbessert.","pt":"Habilita os agentes a escreverem um código TypeScript limpo, composto e escalável, utilizando aliases de tipo, interfaces e tipos de retorno explícitos, reduzindo bugs e aprimorando a clareza do código com recursos como sobrecarga de funções e tratamento de nulabilidade.","ru":"Наделяет агентов возможностью писать чистый, составной и масштабируемый код TypeScript, используя псевдонимы типов, интерфейсы и явные типы возвращаемых значений, сокращая количество ошибок и улучшая ясность кода с помощью функций, таких как перегрузка функций и обработка нуллируемости.","ar":"تمكين العملاء من كتابة رمز TypeScript نظيف ومركب ومقابل للتحجيم باستخدام أسماء مستعارة من النوع وواجهات وأنواع إرجاع صريحة، وتقليل العيوب وتحسين وضوح الرمز باستخدام ميزات مثل переписة الوظائف ومعالجة القيمة الصفرية."},"useCases":{"en":["Enforcing coding standards with type declaration best practices","Generating public APIs with extensible object shapes using interfaces","Improving code readability by handling nullability and preferring explicit return types"],"zh":["使用类型声明最佳实践来执行编码标准","使用接口生成具有可扩展对象形状的公共API","通过处理可空性并更喜欢显式返回类型来提高代码的可读性"],"ja":["タイプ宣言のベストプラクティスを使用してコーディング規約を実施する","インターフェイスを使用して拡張可能なオブジェクトの形状を持つパブリックAPIを生成する","null safetyを処理して明示的な戻り値の型を優先することでコードの可読性を向上させる"],"ko":["타입 선언 모범 사례를 사용하여 코딩 표준을 시행하는 것","인터페이스를 사용하여 확장 가능한 객체 모양을 가진 공용 API를 생성하는 것","널 가능성을 처리하고 명시적 반환 유형을 선호하여 코드의 가독성을 향상시키는 것"],"es":["Aplicar normas de codificación con las mejores prácticas de declaración de tipos","Generar API públicas con formas de objetos extensibles utilizando interfaces","Mejorar la legibilidad del código manejando la nulabilidad y prefiriendo tipos de retorno explícitos"],"fr":["Mettre en œuvre des normes de codage avec les meilleures pratiques de déclaration de types","Générer des API publiques avec des formes d''objets extensibles en utilisant des interfaces","Améliorer la lisibilité du code en gérant la nulabilité et en préférant des types de retour explicites"],"de":["Einführung von Codierungsstandards mit den besten Praktiken für Typdeklarationen","Generierung von öffentlichen APIs mit erweiterbaren Objektformen unter Verwendung von Schnittstellen","Verbesserung der Lesbarkeit des Codes durch Handhabung von Nullität und Bevorzugung expliziter Rückgabetypen"],"pt":["Aplicar padrões de codificação com as melhores práticas de declaração de tipos","Gerar APIs públicas com formas de objeto extensíveis usando interfaces","Melhorar a legibilidade do código, tratando a nulabilidade e preferindo tipos de retorno explícitos"],"ru":["Применение стандартов кодирования с лучшими практиками объявления типов","Генерация публичных API с расширяемыми формами объектов, используя интерфейсы","Улучшение читаемости кода, обрабатывая нуллируемость и предпочитая явные типы возвращаемых значений"],"ar":["تطبيق معايير الترميز مع أفضل الممارسات لإعلان الأنواع","توليد واجهات برمجة التطبيقات العامة بأشكال كائن قابلة للتوسيع باستخدام الواجهات","تحسين قابلية قراءة الرمز، عن طريق معالجة القيمة الصفرية والتفضيل لأنواع الإرجاع الصريحة"]},"limitations":{"en":["Requires TypeScript compiler and compatible IDE setup","Focused on TypeScript best practices, not JavaScript"],"zh":["需要TypeScript编译器和兼容的IDE设置","专注于TypeScript的最佳实践，而不是JavaScript"],"ja":["TypeScriptコンパイラーと互換性のあるIDE設定が必要","TypeScriptのベストプラクティスに焦点を当てているため、JavaScriptには対応していない"],"ko":["TypeScript 컴파일러 및 호환 가능한 IDE 설정이 필요","TypeScript의 모범 사례에 중점을 두고 있으므로 JavaScript에는対応하지 않음"],"es":["Requiere configuración de compilador de TypeScript y entorno de desarrollo integrado compatible","Se centra en las mejores prácticas de TypeScript, no en JavaScript"],"fr":["Nécessite une configuration de compilateur TypeScript et un environnement de développement intégré compatible","Se concentre sur les meilleures pratiques de TypeScript, et non sur JavaScript"],"de":["Benötigt eine Konfiguration des TypeScript-Compilers und eines kompatiblen integrierten Entwicklungsumfelds","Konzentriert sich auf die besten Praktiken für TypeScript, nicht für JavaScript"],"pt":["Exige compilador TypeScript e configuração de IDE compatível","Focado em melhores práticas de TypeScript, não em JavaScript"],"ru":["Требует компилятора TypeScript и совместимой настройки IDE","Сосредоточен на лучших практиках TypeScript, а не на JavaScript"],"ar":["يتطلب مترجم TypeScript وإعداد IDE متوافق","يركز على أفضل الممارسات لبرمجة TypeScript، وليس على JavaScript"]},"version":3},"qualityScore":20}');
