INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AoEiuV020/video_concat/init-import-sorter', 'community', 'AoEiuV020', 'video_concat', 'AoEiuV020/video_concat', 'init-import-sorter', 0, 0, 0, '2026-02-18T01:08:43.408Z', '2026-02-18T03:31:27.190Z', NULL, '{"id":"AoEiuV020/video_concat/init-import-sorter","name":"init-import-sorter","description":{"zh":"init-import-sorter 是一个 Flutter 包装命令，用于调用 FFmpeg 简单合并视频。它可以帮助开发者简化视频处理流程","ja":"init-import-sorter は、FFmpeg を使用してビデオを簡単にマージする Flutter パッケージコマンドです。開発者がビデオ処理のワークフローを簡素化するのに役立ちます","ko":"init-import-sorter는 FFmpeg를 사용하여 비디오를 간단히 병합하는 Flutter 패키지 명령어입니다. 개발자가 비디오 처리 워크플ロー를 간소화하는 데 도움이 됩니다","es":"Init Import Sorter es una herramienta para ordenar importaciones en proyectos Flutter, mejorando la organización y la legibilidad del código","fr":"Init Import Sorter est un outil pour trier les importations dans les projets Flutter, améliorant l''organisation et la lisibilité du code","de":"Init Import Sorter ist ein Werkzeug zur Sortierung von Importen in Flutter-Projekten, das die Organisation und Lesbarkeit des Codes verbessert","pt":"O init-import-sorter é uma ferramenta para organizar importações no Flutter. Ele simplifica o processo de merge de vídeos","ru":"Init-import-sorter - это инструмент для организации импортов в Flutter. Он упрощает процесс объединения видео","ar":"init-import-sorter هو أداة لتنظيم الاستيرادات في الفلاتر. يبسط عملية دمج الفيديو","en":"flutter包装命令方式调用ffmpeg简单合并视频，"},"seo":{"title":{"zh":"init-import-sorter：Flutter 包装命令调用 FFmpeg 简单合并视频","ja":"init-import-sorter：Flutter パッケージコマンドによる FFmpeg ビデオマージ","ko":"init-import-sorter: Flutter 패키지 명령어를 사용한 FFmpeg 비디오 병합","es":"Init Import Sorter: Herramienta de Ordenación de Importac...","fr":"Init Import Sorter : Outil de Tri des Importations","de":"Init Import Sorter: Werkzeug für die Sortierung von Importen","pt":"Organizador de Importações para Flutter","ru":"Сортировщик импортов для Flutter","ar":"موزع استيراد للفلاتر","en":"init-import-sorter"},"description":{"zh":"init-import-sorter 是一个 Flutter 包装命令，用于调用 FFmpeg 简单合并视频。它可以帮助开发者简化视频处理流程","ja":"init-import-sorter は、FFmpeg を使用してビデオを簡単にマージする Flutter パッケージコマンドです。開発者がビデオ処理のワークフローを簡素化するのに役立ちます","ko":"init-import-sorter는 FFmpeg를 사용하여 비디오를 간단히 병합하는 Flutter 패키지 명령어입니다. 개발자가 비디오 처리 워크플ロー를 간소화하는 데 도움이 됩니다","es":"Init Import Sorter es una herramienta para ordenar importaciones en proyectos Flutter, mejorando la organización y la legibilidad del código","fr":"Init Import Sorter est un outil pour trier les importations dans les projets Flutter, améliorant l''organisation et la lisibilité du code","de":"Init Import Sorter ist ein Werkzeug zur Sortierung von Importen in Flutter-Projekten, das die Organisation und Lesbarkeit des Codes verbessert","pt":"O init-import-sorter é uma ferramenta para organizar importações no Flutter. Ele simplifica o processo de merge de vídeos","ru":"Init-import-sorter - это инструмент для организации импортов в Flutter. Он упрощает процесс объединения видео","ar":"init-import-sorter هو أداة لتنظيم الاستيرادات في الفلاتر. يبسط عملية دمج الفيديو","en":"flutter包装命令方式调用ffmpeg简单合并视频，"},"definition":{"en":"flutter包装命令方式调用ffmpeg简单合并视频，"},"features":{"zh":["简化 FFmpeg 视频合并","支持 monorepo pub workspaces","使用 dart pub global activate 安装","通过 melos 对所有包排序","支持单个文件排序","提高开发效率"],"ja":["FFmpeg ビデオマージの簡素化","monorepo pub workspaces のサポート","dart pub global activate を使用したインストール","melos を使用したすべてのパッケージのソート","単一ファイルのソートのサポート","開発効率の向上"],"ko":["FFmpeg 비디오 병합의 간소화","monorepo pub workspaces의 지원","dart pub global activate를 사용한 설치","melos를 사용한 모든 패키지의 정렬","단일 파일의 정렬 지원","개발 효율성의 향상"],"es":["Ordena importaciones de manera automática","Soporta proyectos Flutter y Dart","Compatible con monorepo y pub workspaces","Fácil de instalar y utilizar","Mejora la legibilidad y organización del código"],"fr":["Trie les importations de manière automatique","Prend en charge les projets Flutter et Dart","Compatible avec monorepo et pub workspaces","Facile à installer et à utiliser","Améliore la lisibilité et l''organisation du code"],"de":["Sortiert Importe automatisch","Unterstützt Flutter- und Dart-Projekte","Kompatibel mit monorepo und pub workspaces","Einfach zu installieren und zu verwenden","Verbessert die Lesbarkeit und Organisation des Codes"],"pt":["Organização de importações no Flutter","Suporte a monorepo pub workspaces","Comando simples para ordenar importações","Integração com melos para ordenar pacotes","Suporte a versões fixas do pub"],"ru":["Организация импортов в Flutter","Поддержка monorepo pub workspaces","Простая команда для сортировки импортов","Интеграция с melos для сортировки пакетов","Поддержка исправленных версий pub"],"ar":["تنظيم الاستيرادات في الفلاتر","دعم متعدد المستودعات pub workspaces","أمر بسيط لترتيب الاستيرادات","التكامل مع melos لترتيب الحزم","دعم الإصدارات الثابتة من pub"]},"keywords":{"zh":["init-import-sorter","Flutter","FFmpeg","视频合并","monorepo","pub workspaces","dart pub global activate","melos"],"ja":["init-import-sorter","Flutter","FFmpeg","ビデオマージ","monorepo","pub workspaces","dart pub global activate","melos"],"ko":["init-import-sorter","Flutter","FFmpeg","비디오 병합","monorepo","pub workspaces","dart pub global activate","melos"],"es":["Init Import Sorter","ordenación de importaciones","proyectos Flutter","Dart","monorepo","pub workspaces","herramientas de desarrollo","optimización de código"],"fr":["Init Import Sorter","tri des importations","projets Flutter","Dart","monorepo","pub workspaces","outils de développement","optimisation de code"],"de":["Init Import Sorter","Sortierung von Importen","Flutter-Projekte","Dart","monorepo","pub workspaces","Entwicklerwerkzeuge","Code-Optimierung"],"pt":["init-import-sorter","organizar importações","Flutter","monorepo pub workspaces","melos","pub","dart","desenvolvimento de aplicativos móveis"],"ru":["init-import-sorter","организация импортов","Flutter","monorepo pub workspaces","melos","pub","dart","разработка мобильных приложений"],"ar":["init-import-sorter","تنظيم الاستيرادات","الفلاتر","مستودعات(pub workspaces) متعددة","melos","pub","dart","تطوير تطبيقات الهاتف المحمول"]}},"owner":"AoEiuV020","repo":"video_concat","repoPath":"AoEiuV020/video_concat","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.408Z","topics":[],"category":"community","skillMd":{"name":"init-import-sorter","description":"Install import_sorter for Dart import sorting. Use when user needs import sorting, wants to sort imports, or gets import_sorter not found. Triggers on install import_sorter, init import sorter, sort imports, setup import_sorter.","bodyPreview":"# 安装 Import Sorter\n\n确保 import_sorter 已安装并可用。使用支持 pub workspaces 的修复版本。\n\n## 安装步骤\n\n```bash\n# 1. 检查是否已安装\ndart pub global list | grep import_sorter\n\n# 2. 如果未安装，从修复分支安装（支持 monorepo pub workspaces）\ndart pub global activate --source git https://github.com/myConsciousness/import_sorter.git --git-ref fix/monorepo-pub-workspaces\n```\n\n## 使用\n\n```bash\n# 对单个文件排序\ndart pub global run import_sorter --no-comments\n\n# 通过 melos 对所有包排序\nmelos sort\n```","body":"# 安装 Import Sorter\n\n确保 import_sorter 已安装并可用。使用支持 pub workspaces 的修复版本。\n\n## 安装步骤\n\n```bash\n# 1. 检查是否已安装\ndart pub global list | grep import_sorter\n\n# 2. 如果未安装，从修复分支安装（支持 monorepo pub workspaces）\ndart pub global activate --source git https://github.com/myConsciousness/import_sorter.git --git-ref fix/monorepo-pub-workspaces\n```\n\n## 使用\n\n```bash\n# 对单个文件排序\ndart pub global run import_sorter --no-comments\n\n# 通过 melos 对所有包排序\nmelos sort\n```\n"},"lastSynced":"2026-02-18T03:31:27.190Z","agentAnalysis":{"suitability":{"en":"Perfect for Flutter Agents needing organized Dart import statements and simplified video merging with ffmpeg.","zh":"非常适合需要组织Dart导入语句和使用ffmpeg简化视频合并的Flutter代理。","ja":"Dartのインポート文を整理し、ffmpegを使用してビデオをマージする必要があるFlutterエージェントに最適です。","ko":"Dart导入语句를 정리하고 ffmpeg를 사용하여 비디오를 병합해야 하는 Flutter 에이전트에 적합합니다.","es":"Perfecto para agentes de Flutter que necesitan declaraciones de importación de Dart organizadas y una fusión de video simplificada con ffmpeg.","fr":"Parfait pour les agents Flutter ayant besoin de déclarations d''importation Dart organisées et d''une fusion de vidéos simplifiée avec ffmpeg.","de":"Perfekt für Flutter-Agents, die organisierte Dart-Import-Anweisungen und eine vereinfachte Videozusammenführung mit ffmpeg benötigen.","pt":"Perfeito para agentes Flutter que precisam de declarações de importação Dart organizadas e mesclagem de vídeo simplificada com ffmpeg.","ru":"Идеально для агентов Flutter, которым требуются организованные операторы импорта Dart и упрощенное слияние видео с помощью ffmpeg.","ar":"مثالي لعميلات Flutter التي تتطلب عبارات استيراد Dart المنظمة ودمج الفيديو المبسط باستخدام ffmpeg."},"recommendation":{"en":"Empowers agents to maintain clean codebases with sorted import statements and leverage ffmpeg for video manipulation, utilizing dart pub global and melos for efficient package management and sorting.","zh":"赋予代理维护干净的代码库、排序导入语句的能力，并利用ffmpeg进行视频操作，使用dart pub global和melos进行高效的包管理和排序。","ja":"エージェントがクリーンなコードベースを維持し、インポート文を整理し、ffmpegを使用してビデオ操作を行うことを可能にし、dart pub globalとmelosを使用して効率的なパッケージ管理と整理を行います。","ko":"에이전트가 깨끗한 코드베이스를 유지하고,导入语句를 정렬하며, ffmpeg를 사용하여 비디오操作을 수행할 수 있도록 하며, dart pub global과 melos를 사용하여 효율적인 패키지 관리와 정렬을 수행합니다.","es":"Habilita a los agentes a mantener bases de código limpias con declaraciones de importación ordenadas y a aprovechar ffmpeg para la manipulación de videos, utilizando dart pub global y melos para una gestión y ordenación de paquetes eficientes.","fr":"Autorise les agents à maintenir des bases de code propres avec des déclarations d''importation triées et à exploiter ffmpeg pour la manipulation de vidéos, en utilisant dart pub global et melos pour une gestion et un tri efficaces des paquets.","de":"Ermächtigt die Agents, saubere Codebasen mit sortierten Importanweisungen zu pflegen und ffmpeg für die Videomanipulation zu nutzen, indem dart pub global und melos für eine effiziente Paketverwaltung und -sortierung verwendet werden.","pt":"Habilita os agentes a manterem bases de código limpas com declarações de importação classificadas e a aproveitar o ffmpeg para manipulação de vídeo, utilizando dart pub global e melos para gerenciamento eficiente de pacotes e classificação.","ru":"Наделяет агентов возможностью поддерживать чистые кодовые базы с отсортированными операторами импорта и использовать ffmpeg для манипуляции видео, используя dart pub global и melos для эффективного управления пакетами и сортировки.","ar":"يمنح الوكلاء القدرة على الحفاظ على قواعد بيانات برمجية نظيفة مع عبارات استيراد مصنفة و الاستفادة من ffmpeg لتعديل الفيديو، باستخدام dart pub global و melos لإدارة الحزم والترتيب بكفاءة."},"useCases":{"en":["Sorting import statements in Dart files","Merging videos using ffmpeg commands","Automating code organization with melos"],"zh":["在Dart文件中排序导入语句","使用ffmpeg命令合并视频","使用melos自动化代码组织"],"ja":["Dartファイル内のインポート文の整理","ffmpegコマンドを使用したビデオのマージ","melosを使用したコードの自動整理"],"ko":["Dart 파일 내의导入语句 정렬","ffmpeg 명령을 사용한 비디오 병합","melos를 사용한 코드 자동화"],"es":["Ordenar declaraciones de importación en archivos Dart","Combinar videos utilizando comandos ffmpeg","Automatizar la organización de código con melos"],"fr":["Trier les déclarations d''importation dans les fichiers Dart","Fusionner des vidéos à l''aide de commandes ffmpeg","Automatiser l''organisation du code avec melos"],"de":["Sortieren von Importanweisungen in Dart-Dateien","Zusammenführung von Videos mithilfe von ffmpeg-Befehlen","Automatisierung der Codeorganisation mit melos"],"pt":["Classificação de declarações de importação em arquivos Dart","Mesclagem de vídeos usando comandos ffmpeg","Automatização da organização do código com melos"],"ru":["Сортировка операторов импорта в файлах Dart","Объединение видео с помощью команд ffmpeg","Автоматизация организации кода с помощью melos"],"ar":["ترتيب عبارات الاستيراد في ملفات Dart","دمج مقاطع الفيديو باس