INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('munlucky/code-cafe-manager/implementation-runner', 'community', 'munlucky', 'code-cafe-manager', 'munlucky/code-cafe-manager', 'implementation-runner', 0, 0, 60, '2026-02-18T01:08:43.415Z', '2026-02-18T04:00:25.585Z', NULL, '{"id":"munlucky/code-cafe-manager/implementation-runner","name":"implementation-runner","description":{"zh":"Implementation Runner 1-2","ja":"Implementation Runner","ko":"Implementation Runner 1-2","es":"El ejecutor de implementación es una herramienta que automatiza el proceso de desarrollo, permitiendo a los desarrolladores centrarse en tareas más complejas","fr":"L''exécuteur d''implémentation est un outil qui automatise le processus de développement, permettant aux développeurs de se concentrer sur des tâches plus complexes","de":"Der Implementierungs-Runner ist ein Tool, das den Entwicklungsprozess automatisiert, damit Entwickler sich auf komplexere Aufgaben konzentrieren können","en":""},"seo":{"title":{"zh":"Implementation Runner ","ja":"Implementation Runner","ko":"Implementation Runner","es":"Ejecutor de Implementación: Automatiza el Desarrollo","fr":"Exécuteur d''Implémentation: Automatiser le Développement","de":"Implementierungs-Runner: Automatisieren Sie die Entwicklung","en":"implementation-runner"},"description":{"zh":"Implementation Runner 1-2","ja":"Implementation Runner","ko":"Implementation Runner 1-2","es":"El ejecutor de implementación es una herramienta que automatiza el proceso de desarrollo, permitiendo a los desarrolladores centrarse en tareas más complejas","fr":"L''exécuteur d''implémentation est un outil qui automatise le processus de développement, permettant aux développeurs de se concentrer sur des tâches plus comp...","de":"Der Implementierungs-Runner ist ein Tool, das den Entwicklungsprozess automatisiert, damit Entwickler sich auf komplexere Aufgaben konzentrieren können","en":""},"definition":{"en":""},"features":{"zh":["1. ","2. ","3. ","4. "],"ja":["1. ","2. ","3. ","4. "],"ko":["1. ","2. ","3. ","4. "],"es":["Automatización del proceso de desarrollo","Implementación de cambios en el código","Actualización del contexto de análisis","Registro de archivos modificados y resumen de cambios","Integración con el contexto de análisis"],"fr":["Automatisation du processus de développement","Implémentation de changements dans le code","Mise à jour du contexte d''analyse","Enregistrement des fichiers modifiés et résumé des changements","Intégration avec le contexte d''analyse"],"de":["Automatisierung des Entwicklungsprozesses","Implementierung von Änderungen im Code","Aktualisierung des Analysekontexts","Aufzeichnung der geänderten Dateien und Zusammenfassung der Änderungen","Integration mit dem Analysekontext"]},"keywords":{"zh":["Implementation Runner","SEO","developer","technical","analysisContext","skillChain"],"ja":["Implementation Runner","SEO","developer","technical","analysisContext","skillChain"],"ko":["Implementation Runner","SEO","developer","technical","analysisContext","skillChain"],"es":["ejecutor de implementación","automatización de desarrollo","implementación de cambios","contexto de análisis","desarrollo de software","herramientas de desarrollo"],"fr":["exécuteur d''implémentation","automatisation de développement","implémentation de changements","contexte d''analyse","développement de logiciels","outils de développement"],"de":["Implementierungs-Runner","Automatisierung der Entwicklung","Implementierung von Änderungen","Analysekontext","Software-Entwicklung","Entwicklungstools"]}},"owner":"munlucky","repo":"code-cafe-manager","repoPath":"munlucky/code-cafe-manager","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.415Z","topics":[],"category":"community","skillMd":{"name":"implementation-runner","description":"Performs implementation in the chain and records completion state and changed files in analysisContext. Use during implementation.","bodyPreview":"# Implementation Runner\n\n## Inputs\n- `analysisContext.request.userMessage`\n- `analysisContext.decisions.skillChain`\n- `analysisContext.repo.openFiles`\n- `analysisContext.artifacts.contextDocPath` (if present)\n\n## Procedure\n1. Check requirements and context.\n2. Define change scope and implement.\n3. Record changed files and key change summary.\n4. Update implementation completion in `analysisContext`.\n\n## Output (patch)\n```yaml\nsignals.implementationComplete: true\nrepo.changedFiles:\n  - src/...\nnot","body":"# Implementation Runner\n\n## Inputs\n- `analysisContext.request.userMessage`\n- `analysisContext.decisions.skillChain`\n- `analysisContext.repo.openFiles`\n- `analysisContext.artifacts.contextDocPath` (if present)\n\n## Procedure\n1. Check requirements and context.\n2. Define change scope and implement.\n3. Record changed files and key change summary.\n4. Update implementation completion in `analysisContext`.\n\n## Output (patch)\n```yaml\nsignals.implementationComplete: true\nrepo.changedFiles:\n  - src/...\nnotes:\n  - \"implementation: complete, changed_files=3\"\n```\n\n## Rules\n- Do not call other skills/subagents.\n- If failed or deferred, record the reason in `notes`.\n"},"lastSynced":"2026-02-18T04:00:25.585Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring automated implementation and change tracking capabilities.","zh":"适合需要自动实现和变更跟踪功能的开发代理。","ja":"自動実装と変更追跡機能を必要とする開発エージェントに適しています。","ko":"자동 구현 및 변경 추적 기능을 필요한 개발 에이전트에 적합합니다.","es":"Ideal para Agentes de Desarrollo que requieren implementación automatizada y capacidades de seguimiento de cambios.","fr":"Idéal pour les agents de développement nécessitant une mise en œuvre automatisée et des capacités de suivi des modifications.","de":"Ideal für Entwicklungsmittel, die eine automatisierte Implementierung und Änderungsverfolgungsfunktionen erfordern.","pt":"Ideal para Agentes de Desenvolvimento que requerem implementação automatizada e capacidades de rastreamento de alterações.","ru":"Идеально для агентов разработки, требующих автоматизированной реализации и возможностей отслеживания изменений.","ar":"مثالي لعميل التطوير الذي يتطلب التنفيذ التلقائي وقدرات تتبع التغييرات."},"recommendation":{"en":"Empowers agents to define change scope, implement updates, and record changes in files, utilizing context from user messages, skill chains, and repository files, while updating implementation completion status in the analysis context.","zh":"赋予代理定义变更范围、实施更新和在文件中记录变更的能力，利用来自用户消息、技能链和存储库文件的上下文，同时在分析上下文中更新实施完成状态。","ja":"ユーザーからのメッセージ、スキルチェーン、リポジトリファイルからのコンテキストを利用して、エージェントに変更の範囲を定義し、更新を実施し、ファイルに変更を記録し、分析コンテキストで実施完了ステータスを更新する能力を付与します。","ko":"사용자 메시지, 스킬 체인, 저장소 파일에서 컨텍스트를 사용하여 에이전트가 변경 범위를 정의하고 업데이트를 구현하고 파일에 변경 사항을 기록하고 분석 컨텍스트에서 구현 완료 상태를 업데이트할 수 있는 기능을 부여합니다.","es":"Habilita a los agentes a definir el alcance de los cambios, implementar actualizaciones y registrar los cambios en archivos, utilizando el contexto de los mensajes de los usuarios, las cadenas de habilidades y los archivos del repositorio, mientras se actualiza el estado de finalización de la implementación en el contexto del análisis.","fr":"Permet aux agents de définir la portée des modifications, de mettre en œuvre des mises à jour et d''enregistrer les modifications dans les fichiers, en utilisant le contexte des messages des utilisateurs, des chaînes de compétences et des fichiers du référentiel, tout en mettant à jour le statut d''achèvement de la mise en œuvre dans le contexte d''analyse.","de":"Ermöglicht es den Agenten, den Änderungsumfang zu definieren, Updates zu implementieren und Änderungen in Dateien aufzuzeichnen, indem sie den Kontext der Benutzernachrichten, der Fähigkeitsketten und der Repository-Dateien nutzen, während der Implementierungsabschlussstatus im Analysekontext aktualisiert wird.","pt":"Permite que os agentes definam o escopo da alteração, implementem atualizações e registrem alterações em arquivos, utilizando o contexto das mensagens do usuário, cadeias de habilidades e arquivos do repositório, ao mesmo tempo em que atualiza o status de conclusão da implementação no contexto da análise.","ru":"Наделяет агентов возможностью определять объем изменений, реализовывать обновления и регистрировать изменения в файлах, используя контекст сообщений пользователей, цепочки навыков и файлы репозитория, при этом обновляя статус завершения реализации в контексте анализа.","ar":"يُمكن_AGENT من تحديد نطاق التغيير وتنفيذ التحديثات وتسجيل التغييرات في الملفات، مع استخدام السياق من رسائل المستخدم وسلاسل المهارات وملفات المستودع، مع تحديث حالة إكمال التنفيذ في سياق التحليل."},"useCases":{"en":["Automating implementation updates based on user requests","Tracking changes in repository files for version control","Generating summaries of key changes for development teams"],"zh":["基于用户请求自动实施更新","用于版本控制的存储库文件中的更改跟踪","为开发团队生成关键更改的摘要"],"ja":["ユーザーのリクエストに基づいて自動で実装を更新する","バージョン管理のためにリポジトリファイルの変更を追跡する","開発チームのための重要な変更のサマリーを生成する"],"ko":["사용자 요청에 따라 자동으로 구현을 업데이트하는 것","버전 관리를 위해 저장소 파일의 변경 사항을 추적하는 것","개발 팀을 위한 주요 변경 사항의 요약을 생성하는 것"],"es":["Automatización de actualizaciones de implementación en función de las solicitudes de los usuarios","Seguimiento de los cambios en los archivos del repositorio para el control de versiones","Generación de resúmenes de los cambios clave para los equipos de desarrollo"],"fr":["Automatisation des mises à jour de mise en œuvre en fonction des demandes des utilisateurs","Suivi des modifications dans les fichiers du référentiel pour le contrôle des versions","Génération de résumés des modifications clés pour les équipes de développement"],"de":["Automatisierung von Implementierungsaktualisierungen basierend auf Benutzeranfragen","Nachverfolgung von Änderungen in Repository-Dateien für die Versionskontrolle","Erstellung von Zusammenfassungen der wichtigsten Änderungen für Entwicklungsteams"],"pt":["Automatizar atualizações de implementação com base em solicitações do usuário","Rastrear alterações em arquivos do repositório para controle de versão","Gerar resumos das principais alterações para equipes de desenvolvimento"],"ru":["Автоматизировать обновления реализации на основе запросов пользователей","Отслеживать изменения в файлах репозитория для контроля версий","Генерировать сводки основных изменений для команд разработки"],"ar":["توفير تحديثات التنفيذ تلقائيًا بناءً على طلبات المستخدم","تعقب التغييرات في ملفات المستودع للتحكم في الإصدار","generating ملخصات للتغييرات الرئيسية لفريق التطوير"]},"limitations":{"en":["Requires access to analysis context and repository files","Dependent on presence of contextDocPath for full functionality"],"zh":["需要访问分析上下文和存储库文件","需要contextDocPath存在才能实现全部功能"],"ja":["分析コンテキストとリポジトリファイルへのアクセスが必要","全機能を実現するにはcontextDocPathの存在が必要"],"ko":["분석 컨텍스트와 저장소 파일에 대한 액세스가 필요합니다.","전체 기능을 구현하려면 contextDocPath 존재가 필요합니다."],"es":["Requiere acceso al contexto de análisis y a los archivos del repositorio","Depende de la presencia de contextDocPath para la funcionalidad completa"],"fr":["Nécessite l''accès au contexte d''analyse et aux fichiers du référentiel","Dépend de la présence de contextDocPath pour la fonctionnalité complète"],"de":["Erfordert Zugriff auf den Analysekontext und die Repository-Dateien","Hängt von der Anwesenheit von contextDocPath für die vollständige Funktionalität ab"],"pt":["Requer acesso ao contexto da análise e arquivos do repositório","Depende da presença do contextDocPath para funcionalidade completa"],"ru":["Требует доступа к контексту анализа и файлам репозитория","Зависит от наличия contextDocPath для полной функциональности"],"ar":["يتطلب الوصول إلى سياق التحليل وملفات المستودع","يعتمد على وجود contextDocPath للوظيفة الكاملة"]},"version":3},"qualityScore":60}');
